-- ===========================================================================
-- FLIPMATH9 — NỘI DUNG TOÁN 9 (FLIPMATH9)
-- (Toán 9, Kết nối tri thức với cuộc sống) · BẢN NHÁP, giáo viên duyệt
--
-- TỆP NÀY ĐƯỢC SINH TỰ ĐỘNG bằng lệnh (trong thư mục dfle-engine):
--     node cli/emit-toan-9.js C6,C7,C8,C9,C10 > ../web/supabase/<tệp này>
--
--   Chương VI: 10 đơn vị · 12 mã lỗi · 80 câu · 36 gợi ý · 12 vi bài học
--   Chương VII: 8 đơn vị · 7 mã lỗi · 64 câu · 21 gợi ý · 7 vi bài học
--   Chương VIII: 3 đơn vị · 4 mã lỗi · 24 câu · 12 gợi ý · 4 vi bài học
--   Chương IX: 10 đơn vị · 11 mã lỗi · 80 câu · 33 gợi ý · 11 vi bài học
--   Chương X: 6 đơn vị · 6 mã lỗi · 48 câu · 18 gợi ý · 6 vi bài học
--   Ngân hàng hoạt động Toán 9: 58 hoạt động (bản nháp)
--
-- Chạy trong Supabase → SQL Editor, sau các tệp cấu trúc (xem HUONG-DAN-SUPABASE.md). Đã chạy bản cũ của tệp này thì chạy lại bản mới:
-- nội dung được cập nhật theo bản mới, link video giáo viên đã tự gắn được giữ nguyên.
-- Chạy lại nhiều lần vẫn an toàn (on conflict … do update / do nothing).
-- ===========================================================================

do $$
begin
  if to_regclass('public.knowledge_units') is null then
    raise exception E'\n\n>>> DỪNG LẠI: Phải chạy 01-schema.sql TRƯỚC tệp này. <<<\n';
  end if;
  if to_regclass('public.error_hints') is null then
    raise exception E'\n\n>>> DỪNG LẠI: Phải chạy 05-goi-y-theo-tang.sql TRƯỚC tệp này. <<<\n';
  end if;
  if to_regclass('public.micro_lessons') is null then
    raise exception E'\n\n>>> DỪNG LẠI: Phải chạy 08-vi-bai-hoc.sql TRƯỚC tệp này. <<<\n';
  end if;
  if to_regclass('public.mm_activities') is null then
    raise exception E'\n\n>>> DỪNG LẠI: Phải chạy 35-mathmind.sql TRƯỚC tệp này. <<<\n';
  end if;
end $$;

-- ------------------------------------------------ 0. CỘT HÌNH VẼ / BIỂU ĐỒ CHO CÂU HỎI
-- jsonb: {"loai":"quat"|"doan-thang"|"hinh", ...}. Học sinh được đọc (không chứa đáp án).
alter table public.questions add column if not exists hinh jsonb;
alter table public.contents add column if not exists nguon text;
grant select (hinh) on public.questions to authenticated;

-- Trạng thái duyệt (22/11/2026): nhap | da-duyet | can-sua. Câu "can-sua" bị ẩn khỏi questions_public (học sinh không thấy).
alter table public.questions add column if not exists trang_thai text not null default 'nhap';
alter table public.questions add column if not exists ghi_chu_gv text;
alter table public.questions add column if not exists nguoi_duyet text;
alter table public.questions add column if not exists ngay_duyet date;
do $ck$ begin
  alter table public.questions add constraint questions_trang_thai_ck check (trang_thai in ('nhap', 'da-duyet', 'can-sua'));
exception when duplicate_object then null; end $ck$;
create or replace view public.questions_public
with (security_invoker = true) as
  select question_id, ku_id, level, stem, expected_time_sec, hinh from public.questions where trang_thai <> 'can-sua';
-- View chạy bằng quyền của người xem nên học sinh cần quyền đọc cột trang_thai (không nhạy cảm) để lọc câu.
grant select (trang_thai) on public.questions to authenticated;

