-- Link video: chỉ điền khi ô còn trống — link giáo viên đã tự gắn ở /gv/noi-dung được giữ nguyên.
on conflict (content_id) do update set title = excluded.title, ku_id = excluded.ku_id,
  duration_sec = case when contents.url is null or contents.url = '' then excluded.duration_sec else contents.duration_sec end,
  nguon = case when contents.url is null or contents.url = '' then excluded.nguon else contents.nguon end,
  url = case when contents.url is null or contents.url = '' then excluded.url else contents.url end;

insert into error_dictionary (error_code, ku_id, misconception, remediation_id) values
  ('E-HSB-01', 'C6-B18-M1', 'Tính ax² sai: bình phương cả a·x, quên (−x)² dương, hoặc nhân 2 thay cho bình phương. Ví dụ: y = 2x², x = −3: y = −18 hoặc (2·(−3))² = 36', 'VBH-HSB-01'),
  ('E-HSB-02', 'C6-B18-M2', 'Nhầm hướng parabol theo dấu của a, nhầm trục đối xứng là Ox, hoặc kiểm tra điểm thuộc đồ thị sai. Ví dụ: y = −3x² có O là điểm thấp nhất', 'VBH-HSB-02'),
  ('E-PTB-01', 'C6-B19-M1', 'Đọc hệ số a, b, c không kèm dấu, theo thứ tự xuất hiện, hoặc khi chưa đưa về dạng ax² + bx + c = 0. Ví dụ: 5 − 2x² + x = 0 có a = 5, b = −2, c = 1', 'VBH-PTB-01'),
  ('E-PTB-02', 'C6-B19-M1', 'Giải x² = k chỉ lấy nghiệm dương, cho x² = số âm có nghiệm, hoặc chia cho x làm mất nghiệm 0. Ví dụ: x² − 9 = 0 ⇔ x = 3; x² + 4 = 0 ⇔ x = −2', 'VBH-PTB-02'),
  ('E-PTB-03', 'C6-B19-M2', 'Tính biệt thức sai dấu (b² + 4ac), quên b âm khi bình phương, nhầm b′ với b hoặc dùng 4ac trong Δ′. Ví dụ: x² − 5x + 6 = 0: Δ = 25 + 24 = 49', 'VBH-PTB-03'),
  ('E-PTB-04', 'C6-B19-M2', 'Áp dụng công thức nghiệm sai (quên dấu − của b, quên chia 2a, nhầm 2a với a ở công thức thu gọn) hoặc kết luận số nghiệm sai. Ví dụ: x² − 5x + 6 = 0 có nghiệm −2; −3', 'VBH-PTB-04'),
  ('E-VI-01', 'C6-B20-M1', 'Viết tổng hai nghiệm là b/a (thiếu dấu trừ) hoặc tích là −c/a, đảo tổng với tích. Ví dụ: x² − 7x + 10 = 0 có x1 + x2 = −7', 'VBH-VI-01'),
  ('E-VI-02', 'C6-B20-M1', 'Dùng Viète khi phương trình vô nghiệm, hoặc biến đổi biểu thức đối xứng sai (x1² + x2² = S², 1/x1 + 1/x2 = P/S). Ví dụ: x1² + x2² = (x1 + x2)²', 'VBH-VI-02'),
  ('E-VI-03', 'C6-B20-M2', 'Nhầm hai trường hợp nhẩm nghiệm, quên dấu của nghiệm thứ hai, hoặc dùng b/a thay c/a. Ví dụ: 2x² − 5x + 3 = 0 có nghiệm 1 và 3', 'VBH-VI-03'),
  ('E-VI-04', 'C6-B20-M3', 'Lập phương trình X² + SX + P = 0 (sai dấu), nhầm S với P, hoặc kết luận có hai số khi S² < 4P. Ví dụ: Tổng 7, tích 12: giải X² + 7X + 12 = 0 được −3, −4', 'VBH-VI-04'),
  ('E-LPT-01', 'C6-B21-M1', 'Lập phương trình sai quan hệ (dùng chu vi thay diện tích, lối đi chỉ trừ một bên), hoặc giữ nghiệm âm, nghiệm không thoả điều kiện. Ví dụ: Chiều rộng là 6 m hoặc −10 m', 'VBH-LPT-01'),
  ('E-LPT-02', 'C6-B21-M2', 'Lập phương trình chứa ẩn ở mẫu sai thứ tự hiệu thời gian, nhân thay vì chia, hoặc nhầm năng suất thực tế với dự định. Ví dụ: Tăng tốc đến sớm 1 giờ: 120/(x + 10) − 120/x = 1', 'VBH-LPT-02')
on conflict (error_code) do update set ku_id = excluded.ku_id, misconception = excluded.misconception,
  remediation_id = excluded.remediation_id;

