insert into error_hints (error_code, tier, hint_text) values
  ('E-HSB-01', 1, 'Trong $ax^{2}$, phép bình phương áp dụng cho $x$ hay cho cả $a\cdot x$? Bình phương một số âm ra số gì?'),
  ('E-HSB-01', 2, 'Tính $x^{2}$ trước (luôn không âm), rồi nhân với $a$. Không bình phương $a$. $(-3)^{2} = 9$.'),
  ('E-HSB-01', 3, 'Ví dụ: $y = 2x^{2}$, $x = -3$: $y = 2\cdot 9 = 18$; $s = 5t^{2}$, $t = 3$: $s = 5\cdot 9 = 45$ m.'),
  ('E-HSB-02', 1, 'Hệ số $a$ dương hay âm? Đồ thị đối xứng qua trục nào?'),
  ('E-HSB-02', 2, 'Đồ thị $y = ax^{2}$ là parabol đỉnh $O$, đối xứng qua $Oy$. $a > 0$: nằm trên $Ox$, $O$ là điểm thấp nhất; $a < 0$: nằm dưới $Ox$, $O$ là điểm cao nhất. Điểm $(x_{0}; y_{0})$ thuộc đồ thị khi $y_{0} = a\cdot x_{0}^{2}$.'),
  ('E-HSB-02', 3, 'Ví dụ: $(1; 2)$ thuộc $y = 2x^{2}$ thì $(-1; 2)$ cũng thuộc; $y = -3x^{2}$ có $O$ là điểm cao nhất.'),
  ('E-PTB-01', 1, 'Phương trình đã được sắp xếp theo thứ tự $x^{2}$, $x$, số hạng tự do chưa?'),
  ('E-PTB-01', 2, 'Đưa về $ax^{2} + bx + c = 0$ (sắp xếp theo luỹ thừa giảm dần), rồi đọc $a$, $b$, $c$ kèm dấu đứng trước. Cần $a \ne 0$.'),
  ('E-PTB-01', 3, 'Ví dụ: $5 - 2x^{2} + x = 0 \Leftrightarrow -2x^{2} + x + 5 = 0$: $a = -2$, $b = 1$, $c = 5$.'),
  ('E-PTB-02', 1, 'Số nào bình phương lên bằng $9$? Có mấy số như vậy? Có số nào bình phương ra số âm không?'),
  ('E-PTB-02', 2, '$x^{2} = k$: $k > 0$ thì $x = \pm \sqrt{k}$; $k = 0$ thì $x = 0$; $k < 0$ thì vô nghiệm. Phương trình $ax^{2} + bx = 0$ đặt $x$ chung: $x(ax + b) = 0$.'),
  ('E-PTB-02', 3, 'Ví dụ: $x^{2} = 9 \Leftrightarrow x = \pm 3$; $2x^{2} + 6x = 0 \Leftrightarrow 2x(x + 3) = 0 \Leftrightarrow x = 0$ hoặc $x = -3$.'),
  ('E-PTB-03', 1, 'Em đã thay $b$ kèm dấu vào $b^{2}$ chưa? Giữa $b^{2}$ và $4ac$ là dấu gì?'),
  ('E-PTB-03', 2, '$\Delta = b^{2} - 4ac$ ($b^{2}$ luôn không âm). Nếu $b = 2b''$ thì $\Delta '' = b''^{2} - ac$ (không có số $4$).'),
  ('E-PTB-03', 3, 'Ví dụ: $x^{2} - 5x + 6 = 0$: $\Delta = (-5)^{2} - 4\cdot 1\cdot 6 = 1$; $x^{2} - 6x + 5 = 0$: $b'' = -3$, $\Delta '' = 9 - 5 = 4$.'),
  ('E-PTB-04', 1, '$\Delta$ dương, bằng $0$ hay âm? Trong công thức nghiệm, $-b$ nghĩa là gì và mẫu là $a$ hay $2a$?'),
  ('E-PTB-04', 2, '$\Delta > 0$: $x1{,}2 = (-b \pm \sqrt{\,}\Delta )/(2a)$; $\Delta = 0$: nghiệm kép $x = -b/(2a)$; $\Delta < 0$: vô nghiệm. Công thức thu gọn: $x = (-b'' \pm \sqrt{\,}\Delta '')/a$.'),
  ('E-PTB-04', 3, 'Ví dụ: $x^{2} - 5x + 6 = 0$, $\Delta = 1$: $x = (5 \pm 1)/2$, tức $x = 3$; $x = 2$.'),
  ('E-VI-01', 1, 'Trong hệ thức Viète, tổng hai nghiệm có dấu trừ ở đâu?'),
  ('E-VI-01', 2, '$x_{1} + x_{2} = -\dfrac{b}{a}$ (có dấu trừ), $x_{1}x_{2} = \dfrac{c}{a}$. Đọc $b$, $c$ kèm dấu.'),
  ('E-VI-01', 3, 'Ví dụ: $x^{2} - 7x + 10 = 0$: $x_{1} + x_{2} = 7$, $x_{1}x_{2} = 10$.'),
  ('E-VI-02', 1, 'Phương trình có nghiệm không $(\Delta \ge 0)$? Em có thể viết $x_{1}^{2} + x_{2}^{2}$ qua tổng và tích không?'),
  ('E-VI-02', 2, 'Chỉ dùng Viète khi $\Delta \ge 0$. Biến đổi về $S = x_{1} + x_{2}$, $P = x_{1}x_{2}$: $x_{1}^{2} + x_{2}^{2} = S^{2} - 2P$; $1/x_{1} + 1/x_{2} = \dfrac{S}{P}$; $x_{1}/x_{2} + x_{2}/x_{1} = (S^{2} - 2P)/P$.'),
  ('E-VI-02', 3, 'Ví dụ: $x^{2} - 5x + 3 = 0 (\Delta = 13 > 0)$: $S = 5$, $P = 3$, $x_{1}^{2} + x_{2}^{2} = 25 - 6 = 19$.'),
  ('E-VI-03', 1, '$a + b + c$ bằng $0$ hay $a - b + c$ bằng $0$?'),
  ('E-VI-03', 2, '$a + b + c = 0$: $x_{1} = 1$, $x_{2} = \dfrac{c}{a}$. $a - b + c = 0$: $x_{1} = -1$, $x_{2} = -\dfrac{c}{a}$.'),
  ('E-VI-03', 3, 'Ví dụ: $2x^{2} - 5x + 3 = 0$ có $2 - 5 + 3 = 0$ nên $x = 1$, $x = \dfrac{3}{2}$; $3x^{2} + 7x + 4 = 0$ có $3 - 7 + 4 = 0$ nên $x = -1$, $x = -\dfrac{4}{3}$.'),
  ('E-VI-04', 1, 'Phương trình nhận hai số có tổng $S$, tích $P$ làm nghiệm: hệ số của $X$ mang dấu gì?'),
  ('E-VI-04', 2, 'Hai số cần tìm là nghiệm của $X^{2} - SX + P = 0$. Có hai số như vậy khi $S^{2} - 4P \ge 0$.'),
  ('E-VI-04', 3, 'Ví dụ: tổng $7$, tích $12$: $X^{2} - 7X + 12 = 0 \Leftrightarrow X = 3$ hoặc $X = 4$; tổng $2$, tích $5$: $4 - 20 < 0$ nên không có.'),
  ('E-LPT-01', 1, 'Ẩn có điều kiện gì (dương, nguyên)? Giải xong em đã loại nghiệm không phù hợp chưa?'),
  ('E-LPT-01', 2, 'Chọn ẩn kèm đơn vị và điều kiện; dịch đề cẩn thận (diện tích, cạnh huyền, lối đi hai bên thì trừ $2x$); giải xong đối chiếu điều kiện, loại nghiệm âm hoặc vô lí.'),
  ('E-LPT-01', 3, 'Ví dụ: $x(x + 4) = 60 \Leftrightarrow x = 6$ hoặc $x = -10$; chiều rộng dương nên $x = 6$ m.'),
  ('E-LPT-02', 1, 'Thời gian bằng quãng đường chia cho gì? Đi nhanh hơn thì thời gian mới lớn hơn hay nhỏ hơn thời gian cũ?'),
  ('E-LPT-02', 2, 'Thời gian $=$ quãng đường : vận tốc; năng suất $=$ khối lượng : thời gian. "Đến sớm $1$ giờ" nghĩa là thời gian cũ $-$ thời gian mới $= 1$.'),
  ('E-LPT-02', 3, 'Ví dụ: $120$ km, tăng $10$ km/h thì sớm $1$ giờ: $\dfrac{120}{x} - 120/(x + 10) = 1 \Rightarrow x = 30$ km/h.')
on conflict (error_code, tier) do update set hint_text = excluded.hint_text;

insert into micro_lessons (content_id, dan, quy_tac, vi_du, tu_lam) values
  ('VBH-HSB-01', '$y = ax^{2}$: "bình phương trước, nhân sau" — đổi thứ tự là sai.', 'Tính $x^{2}$, rồi nhân với $a$. $(-x)^{2} = x^{2}$ luôn không âm.', '[{"de":"$y = 2x^{2}$, $x = -3$.","giai":"Cách nghĩ sai: $y = -18$ hoặc $(2\\cdot (-3))^{2} = 36$. Cách đúng: $y = 2\\cdot 9 = 18$."},{"de":"Đồ thị $y = ax^{2}$ qua $(2; 8)$, tìm $a$.","giai":"$8 = a\\cdot 4 \\Leftrightarrow a = 2$."}]'::jsonb, '[{"de":"$y = -x^{2}$, $x = 4$?","dapAn":"$-16$","giaiThich":"$-(16)$.","dapAnGoc":"−16"},{"de":"$s = 5t^{2}$, $t = 3$?","dapAn":"$45$","giaiThich":"$5\\cdot 9$.","dapAnGoc":"45"}]'::jsonb),
  ('VBH-HSB-02', 'Parabol $y = ax^{2}$ luôn "mở" theo dấu của $a$ và luôn cân đối qua trục tung.', 'Đỉnh $O$, trục đối xứng $Oy$. $a > 0$: nằm trên $Ox$, $O$ thấp nhất; $a < 0$: nằm dưới $Ox$, $O$ cao nhất. Điểm $(x; y)$ thuộc đồ thị thì $(-x; y)$ cũng thuộc.', '[{"de":"$y = -3x^{2}$ có điểm thấp nhất là $O$?","giai":"Cách nghĩ sai: có. Cách đúng: $a = -3 < 0$ nên $O$ là điểm cao nhất."},{"de":"$(1; 2)$ thuộc $y = 2x^{2}$, điểm nào cũng thuộc?","giai":"$(-1; 2)$ (đối xứng qua $Oy$)."}]'::jsonb, '[{"de":"$y = 2x^{2}$ nằm phía nào của $Ox$?","dapAn":"Phía trên","giaiThich":"$a > 0$.","dapAnGoc":"Phía trên"},{"de":"$(2; -4)$ có thuộc $y = -x^{2}$?","dapAn":"Có","giaiThich":"$-(2^{2}) = -4$.","dapAnGoc":"Có"}]'::jsonb),
  ('VBH-PTB-01', 'Đọc hệ số chỉ đúng khi phương trình đã "xếp hàng" $ax^{2} + bx + c = 0$.', 'Chuyển hết về một vế, sắp xếp theo $x^{2}$, $x$, số hạng tự do; $a$, $b$, $c$ lấy kèm dấu. $a \ne 0$.', '[{"de":"$5 - 2x^{2} + x = 0$.","giai":"Cách nghĩ sai: $a = 5$, $b = -2$, $c = 1$. Cách đúng: $-2x^{2} + x + 5 = 0$ nên $a = -2$, $b = 1$, $c = 5$."},{"de":"$3x^{2} - 5x - 2 = 0$.","giai":"$a = 3$, $b = -5$, $c = -2$."}]'::jsonb, '[{"de":"$x^{2} - 4 = 0$ có $b =$ ?","dapAn":"$0$","giaiThich":"Khuyết $x$.","dapAnGoc":"0"},{"de":"$0x^{2} + 2x - 1 = 0$ có phải bậc hai?","dapAn":"Không","giaiThich":"$a = 0$.","dapAnGoc":"Không"}]'::jsonb),
  ('VBH-PTB-02', 'Phương trình khuyết giải nhanh, nhưng dễ bỏ sót nghiệm âm hoặc nghiệm $0$.', '$x^{2} = k$: $k > 0 \to x = \pm \sqrt{k}$; $k < 0 \to$ vô nghiệm. $ax^{2} + bx = 0 \to x(ax + b) = 0 \to x = 0$ hoặc $x = -\dfrac{b}{a}$. $(x + m)^{2} = k > 0 \to x + m = \pm \sqrt{k}$.', '[{"de":"$x^{2} - 9 = 0$.","giai":"Cách nghĩ sai: $x = 3$. Cách đúng: $x^{2} = 9 \\Leftrightarrow x = 3$ hoặc $x = -3$."},{"de":"$2x^{2} + 6x = 0$.","giai":"$2x(x + 3) = 0 \\Leftrightarrow x = 0$ hoặc $x = -3$."}]'::jsonb, '[{"de":"$x^{2} + 4 = 0$?","dapAn":"Vô nghiệm","giaiThich":"$x^{2}$ không âm.","dapAnGoc":"Vô nghiệm"},{"de":"$(x - 2)^{2} = 9$?","dapAn":"$x = 5$; $x = -1$","giaiThich":"$x - 2 = \\pm 3$.","dapAnGoc":"x = 5; x = −1"}]'::jsonb),
  ('VBH-PTB-03', '$\Delta$ là "máy dò" số nghiệm. Tính sai $\Delta$ là mọi bước sau đều sai.', '$\Delta = b^{2} - 4ac$ ($b^{2}$ không âm dù $b$ âm). Khi $b$ chẵn, $b = 2b''$: $\Delta '' = b''^{2} - ac$ (không có số $4$).', '[{"de":"$x^{2} - 5x + 6 = 0$, tính $\\Delta$.","giai":"Cách nghĩ sai: $25 + 24 = 49$. Cách đúng: $25 - 24 = 1$."},{"de":"$x^{2} - 6x + 5 = 0$, tính $\\Delta ''$.","giai":"$b'' = -3$, $\\Delta '' = 9 - 5 = 4$."}]'::jsonb, '[{"de":"$2x^{2} - 3x + 5$: $\\Delta$?","dapAn":"$-31$","giaiThich":"$9 - 40$.","dapAnGoc":"−31"},{"de":"$x^{2} + 8x + 7$: $\\Delta ''$?","dapAn":"$9$","giaiThich":"$16 - 7$.","dapAnGoc":"9"}]'::jsonb),
  ('VBH-PTB-04', 'Có $\Delta$ rồi, chỉ cần lắp đúng công thức — nhớ dấu trừ trước $b$ và mẫu $2a$.', '$\Delta > 0$: $x = (-b \pm \sqrt{\,}\Delta )/(2a)$. $\Delta = 0$: nghiệm kép $-b/(2a)$. $\Delta < 0$: vô nghiệm. Thu gọn: $x = (-b'' \pm \sqrt{\,}\Delta '')/a$.', '[{"de":"$x^{2} - 5x + 6 = 0 (\\Delta = 1)$.","giai":"Cách nghĩ sai: $x = -2$; $-3$. Cách đúng: $x = (5 \\pm 1)/2$, tức $x = 3$; $x = 2$."},{"de":"$x^{2} - 4x + 4 = 0$.","giai":"$\\Delta = 0$, nghiệm kép $x = \\dfrac{4}{2} = 2$."}]'::jsonb, '[{"de":"$2x^{2} + x - 3 = 0$?","dapAn":"$x = 1$; $x = -\\dfrac{3}{2}$","giaiThich":"$\\Delta = 25$.","dapAnGoc":"x = 1; x = −3/2"},{"de":"$x^{2} - 2x + m = 0$ có $2$ nghiệm phân biệt khi?","dapAn":"$m < 1$","giaiThich":"$\\Delta '' = 1 - m > 0$.","dapAnGoc":"m < 1"}]'::jsonb),
  ('VBH-VI-01', 'Hệ thức Viète có một dấu trừ rất dễ quên — ở tổng.', '$x_{1} + x_{2} = -\dfrac{b}{a}$, $x_{1}x_{2} = \dfrac{c}{a}$.', '[{"de":"$x^{2} - 7x + 10 = 0$, tổng hai nghiệm?","giai":"Cách nghĩ sai: $-7$. Cách đúng: $-(-7)/1 = 7$ (nghiệm $2$ và $5$)."},{"de":"$2x^{2} + 5x - 3 = 0$, tích hai nghiệm?","giai":"$\\dfrac{c}{a} = -\\dfrac{3}{2}$."}]'::jsonb, '[{"de":"$x^{2} + 3x - 4 = 0$: $S$?","dapAn":"$-3$","giaiThich":"$-\\dfrac{b}{a}$.","dapAnGoc":"−3"},{"de":"Cùng phương trình, $P$?","dapAn":"$-4$","giaiThich":"$\\dfrac{c}{a}$.","dapAnGoc":"−4"}]'::jsonb),
  ('VBH-VI-02', 'Trước khi dùng Viète, kiểm tra phương trình có nghiệm. Sau đó, mọi biểu thức đối xứng đều đưa được về $S$ và $P$.', 'Cần $\Delta \ge 0$. $x_{1}^{2} + x_{2}^{2} = S^{2} - 2P$; $1/x_{1} + 1/x_{2} = \dfrac{S}{P}$; $x_{1}/x_{2} + x_{2}/x_{1} = (S^{2} - 2P)/P$.', '[{"de":"$x^{2} - 5x + 3 = 0$, tính $x_{1}^{2} + x_{2}^{2}$.","giai":"Cách nghĩ sai: $S^{2} = 25$. Cách đúng: $25 - 2\\cdot 3 = 19$."},{"de":"$x^{2} + 2x + 5 = 0$ có tổng nghiệm $-2$?","giai":"$\\Delta '' = 1 - 5 < 0$, vô nghiệm, không dùng Viète."}]'::jsonb, '[{"de":"$S = 5$, $P = 3$: $1/x_{1} + 1/x_{2}$?","dapAn":"$\\dfrac{5}{3}$","giaiThich":"$\\dfrac{S}{P}$.","dapAnGoc":"5/3"},{"de":"$S = 2$, $P = -1$: $x_{1}/x_{2} + x_{2}/x_{1}$?","dapAn":"$-6$","giaiThich":"$(4 + 2)/(-1)$.","dapAnGoc":"−6"}]'::jsonb),
  ('VBH-VI-03', 'Hai mẹo nhẩm nghiệm: cộng $a + b + c$, hoặc $a - b + c$.', '$a + b + c = 0 \to$ nghiệm $1$ và $\dfrac{c}{a}$. $a - b + c = 0 \to$ nghiệm $-1$ và $-\dfrac{c}{a}$.', '[{"de":"$2x^{2} - 5x + 3 = 0$.","giai":"Cách nghĩ sai: $1$ và $3$. Cách đúng: $2 - 5 + 3 = 0$, nghiệm $1$ và $\\dfrac{c}{a} = \\dfrac{3}{2}$."},{"de":"$3x^{2} + 7x + 4 = 0$.","giai":"$3 - 7 + 4 = 0$, nghiệm $-1$ và $-\\dfrac{4}{3}$."}]'::jsonb, '[{"de":"$x^{2} - 2025x + 2024 = 0$?","dapAn":"$1$; $2024$","giaiThich":"$a + b + c = 0$.","dapAnGoc":"1; 2024"},{"de":"$x^{2} + 5x + 4 = 0$?","dapAn":"$-1$; $-4$","giaiThich":"$a - b + c = 0$.","dapAnGoc":"−1; −4"}]'::jsonb),
  ('VBH-VI-04', 'Biết tổng và tích là dựng được phương trình bậc hai có hai số đó làm nghiệm.', 'Hai số có tổng $S$, tích $P$ là nghiệm của $X^{2} - SX + P = 0$; tồn tại khi $S^{2} - 4P \ge 0$.', '[{"de":"Tổng $7$, tích $12$.","giai":"Cách nghĩ sai: $X^{2} + 7X + 12 = 0$ nên $-3$, $-4$. Cách đúng: $X^{2} - 7X + 12 = 0$ nên $3$ và $4$."},{"de":"Chu vi $28$, diện tích $48$.","giai":"$S = 14$, $P = 48$: $X^{2} - 14X + 48 = 0$, hai cạnh $6$ và $8$."}]'::jsonb, '[{"de":"Tổng $1$, tích $-6$?","dapAn":"$3$ và $-2$","giaiThich":"$X^{2} - X - 6 = 0$.","dapAnGoc":"3 và −2"},{"de":"Tổng $2$, tích $5$ có không?","dapAn":"Không","giaiThich":"$4 - 20 < 0$.","dapAnGoc":"Không"}]'::jsonb),
  ('VBH-LPT-01', 'Phương trình bậc hai thường cho hai nghiệm — nhưng bài toán thực tế có thể chỉ nhận một.', 'Chọn ẩn, đơn vị, điều kiện. Lập phương trình theo đúng đại lượng (diện tích, cạnh huyền…). Giải, rồi loại nghiệm không thoả điều kiện.', '[{"de":"Dài hơn rộng $4$ m, diện tích $60$ m².","giai":"Cách nghĩ sai: rộng $6$ m hoặc $-10$ m. Cách đúng: $x > 0$ nên loại $-10$, chiều rộng $6$ m."},{"de":"Vườn $20 \\times 30$, lối đi rộng $x$ quanh vườn, còn $336$ m².","giai":"$(20 - 2x)(30 - 2x) = 336 \\Leftrightarrow x = 3$ hoặc $x = 22$; $30 - 2x > 0$ và $20 - 2x > 0$ nên $x = 3$."}]'::jsonb, '[{"de":"Hai số tự nhiên liên tiếp có tích $56$?","dapAn":"$7$ và $8$","giaiThich":"$x(x + 1) = 56$.","dapAnGoc":"7 và 8"},{"de":"Nghiệm $x = -8$ cho cạnh tam giác được không?","dapAn":"Không","giaiThich":"Độ dài dương.","dapAnGoc":"Không"}]'::jsonb),
  ('VBH-LPT-02', 'Bài toán "đến sớm", "xong sớm": thời gian cũ trừ thời gian mới.', 'Thời gian $=$ quãng đường : vận tốc; số ngày $=$ khối lượng : năng suất. Đi nhanh hơn thì thời gian ngắn hơn: $t$ cũ $- t$ mới $=$ số giờ sớm.', '[{"de":"$120$ km, tăng $10$ km/h thì sớm $1$ giờ.","giai":"Cách nghĩ sai: $120/(x + 10) - \\dfrac{120}{x} = 1$. Cách đúng: $\\dfrac{120}{x} - 120/(x + 10) = 1 \\Rightarrow x = 30$."},{"de":"$480$ bộ, mỗi ngày thêm $10$ bộ thì xong sớm $4$ ngày.","giai":"$\\dfrac{480}{x} - 480/(x + 10) = 4 \\Rightarrow x = 30$ bộ$/$ngày."}]'::jsonb, '[{"de":"Quãng $60$ km, vận tốc $x$, thời gian?","dapAn":"$\\dfrac{60}{x}$","giaiThich":"$s : v$.","dapAnGoc":"60/x"},{"de":"Cùng chảy $6$ giờ, vòi I nhanh hơn $5$ giờ, vòi I?","dapAn":"$10$ giờ","giaiThich":"$\\dfrac{1}{x} + 1/(x + 5) = \\dfrac{1}{6}$.","dapAnGoc":"10 giờ"}]'::jsonb)
on conflict (content_id) do update set dan = excluded.dan, quy_tac = excluded.quy_tac,
  vi_du = excluded.vi_du, tu_lam = excluded.tu_lam, updated_at = now();

