  ('VBH-TS-01', 'C7-B22-M1', 'micro-lesson', 1, 'Vi bài học: Tần số là số lần giá trị xuất hiện; tổng tần số = N', 300, null, null),
  ('VBH-TS-02', 'C7-B22-M2', 'micro-lesson', 1, 'Vi bài học: Chiều cao cột (điểm) là tần số; trục ngang là giá trị', 300, null, null),
  ('VBH-TSTD-01', 'C7-B23-M1', 'micro-lesson', 1, 'Vi bài học: f = m/N · 100%; tổng các f = 100%', 300, null, null),
  ('VBH-TSTD-02', 'C7-B23-M2', 'micro-lesson', 1, 'Vi bài học: Góc ở tâm = f · 360°', 300, null, null),
  ('VBH-GN-01', 'C7-B24-M1', 'micro-lesson', 1, 'Vi bài học: Nhóm [a; b) lấy a, không lấy b', 300, null, null),
  ('VBH-GN-02', 'C7-B24-M2', 'micro-lesson', 1, 'Vi bài học: Tần số nhóm = số giá trị trong nhóm; đại diện = trung điểm', 360, null, null),
  ('VBH-GN-03', 'C7-B24-M4', 'micro-lesson', 1, 'Vi bài học: Cột liền nhau; đường gấp khúc qua giá trị đại diện', 300, null, null)
-- Link video: chỉ điền khi ô còn trống — link giáo viên đã tự gắn ở /gv/noi-dung được giữ nguyên.
on conflict (content_id) do update set title = excluded.title, ku_id = excluded.ku_id,
  duration_sec = case when contents.url is null or contents.url = '' then excluded.duration_sec else contents.duration_sec end,
  nguon = case when contents.url is null or contents.url = '' then excluded.nguon else contents.nguon end,
  url = case when contents.url is null or contents.url = '' then excluded.url else contents.url end;

insert into error_dictionary (error_code, ku_id, misconception, remediation_id) values
  ('E-TS-01', 'C7-B22-M1', 'Nhầm giá trị với tần số, đếm thiếu hoặc thừa, cộng các giá trị thay cho các tần số khi tìm cỡ mẫu. Ví dụ: Giá trị 7 xuất hiện 4 lần nhưng ghi tần số là 7', 'VBH-TS-01'),
  ('E-TS-02', 'C7-B22-M2', 'Đọc biểu đồ nhầm trục, kết luận theo vị trí cột thay vì chiều cao, hoặc chọn loại biểu đồ không phù hợp. Ví dụ: Cột điểm 9 ở xa nhất nên điểm 9 nhiều bạn nhất', 'VBH-TS-02'),
  ('E-TSTD-01', 'C7-B23-M1', 'Tính tần số tương đối bằng N/m, viết thẳng tần số thành phần trăm, hoặc so sánh hai mẫu cỡ khác nhau bằng tần số. Ví dụ: Lớp 40 bạn, 10 bạn thích bóng đá: tần số tương đối 10%', 'VBH-TSTD-01'),
  ('E-TSTD-02', 'C7-B23-M2', 'Lấy góc ở tâm bằng chính số phần trăm, nhân với 180°, hoặc đọc phần trăm thành số người. Ví dụ: Hình quạt 25% có góc 25°', 'VBH-TSTD-02'),
  ('E-GN-01', 'C7-B24-M1', 'Xếp giá trị bằng đầu mút phải vào nhóm [a; b), đếm một giá trị vào hai nhóm, hoặc tính độ dài nhóm sai. Ví dụ: 160 thuộc nhóm [155; 160)', 'VBH-GN-01'),
  ('E-GN-02', 'C7-B24-M2', 'Đếm tần số nhóm sai, cộng sai tỉ lệ các nhóm, hoặc ước lượng trung bình mà không dùng giá trị đại diện và tần số. Ví dụ: Trung bình = trung bình cộng các giá trị đại diện, không nhân tần số', 'VBH-GN-02'),
  ('E-GN-03', 'C7-B24-M4', 'Vẽ cột tách rời, đặt điểm của biểu đồ đoạn thẳng ở đầu mút nhóm, hoặc so sánh hai mẫu cỡ khác nhau bằng tần số. Ví dụ: Đặt điểm của nhóm [0; 10) tại hoành độ 0', 'VBH-GN-03')
on conflict (error_code) do update set ku_id = excluded.ku_id, misconception = excluded.misconception,
  remediation_id = excluded.remediation_id;

insert into questions (question_id, ku_id, level, stem, correct_option, expected_time_sec, hinh, trang_thai, ghi_chu_gv, nguoi_duyet, ngay_duyet) values
  ('C7-B22-M1-Q01', 'C7-B22-M1', 1, 'Điểm kiểm tra của $10$ bạn: $7$; $8$; $7$; $9$; $6$; $7$; $8$; $9$; $7$; $10$. Tần số của giá trị $7$ là:', 'A', 45, null, 'nhap', null, null, null),
  ('C7-B22-M1-Q02', 'C7-B22-M1', 1, 'Trong một bảng tần số, tổng các tần số bằng:', 'A', 45, null, 'nhap', null, null, null),
  ('C7-B22-M1-Q03', 'C7-B22-M1', 2, 'Số con của $12$ gia đình: $1$; $2$; $2$; $3$; $1$; $2$; $0$; $2$; $1$; $3$; $2$; $1$. Với các giá trị $0$; $1$; $2$; $3$, các tần số tương ứng là:', 'A', 60, null, 'nhap', null, null, null),
  ('C7-B22-M1-Q04', 'C7-B22-M1', 2, 'Bảng tần số cỡ giày của một nhóm bạn: cỡ $36$, $37$, $38$, $39$ có tần số lần lượt $3$, $7$, $6$, $4$. Số bạn được khảo sát là:', 'A', 60, null, 'nhap', null, null, null),
  ('C7-B22-M1-Q05', 'C7-B22-M1', 3, 'Bảng tần số cỡ giày: cỡ $36$, $37$, $38$, $39$ có tần số lần lượt $3$, $7$, $6$, $4$. Cỡ giày có nhiều bạn đi nhất là:', 'A', 90, null, 'nhap', null, null, null),
  ('C7-B22-M1-Q06', 'C7-B22-M1', 3, 'Một mẫu có $30$ số liệu, bảng tần số có các tần số $5$; $8$; $x$; $7$. Giá trị của $x$ là:', 'A', 90, null, 'nhap', null, null, null),
  ('C7-B22-M1-Q07', 'C7-B22-M1', 4, 'Số lỗi chính tả của $20$ học sinh: $6$ bạn không có lỗi, $7$ bạn $1$ lỗi, $4$ bạn $2$ lỗi, $3$ bạn $3$ lỗi. Tổng số lỗi của cả nhóm là:', 'A', 120, null, 'nhap', null, null, null),
  ('C7-B22-M1-Q08', 'C7-B22-M1', 4, 'Số lỗi chính tả của $20$ học sinh: $6$ bạn không có lỗi, $7$ bạn $1$ lỗi, $4$ bạn $2$ lỗi, $3$ bạn $3$ lỗi. Số bạn mắc ít nhất $2$ lỗi là:', 'A', 120, null, 'nhap', null, null, null),
  ('C7-B22-M2-Q01', 'C7-B22-M2', 1, 'Trong biểu đồ cột biểu diễn bảng tần số, chiều cao mỗi cột biểu thị:', 'A', 45, null, 'nhap', null, null, null),
  ('C7-B22-M2-Q02', 'C7-B22-M2', 1, 'Biểu đồ đoạn thẳng biểu diễn bảng tần số có trục nằm ngang ghi:', 'A', 45, null, 'nhap', null, null, null),
  ('C7-B22-M2-Q03', 'C7-B22-M2', 2, 'Biểu đồ cột cho biết điểm kiểm tra của một nhóm: điểm $6$ có $3$ bạn, điểm $7$ có $8$ bạn, điểm $8$ có $6$ bạn, điểm $9$ có $3$ bạn. Số bạn đạt điểm $8$ là:', 'A', 60, null, 'nhap', null, null, null),
  ('C7-B22-M2-Q04', 'C7-B22-M2', 2, 'Biểu đồ cột cho biết điểm kiểm tra của một nhóm: điểm $6$ có $3$ bạn, điểm $7$ có $8$ bạn, điểm $8$ có $6$ bạn, điểm $9$ có $3$ bạn. Số học sinh được khảo sát là:', 'A', 60, null, 'nhap', null, null, null),
  ('C7-B22-M2-Q05', 'C7-B22-M2', 3, 'Biểu đồ cột cho biết điểm kiểm tra của một nhóm: điểm $6$ có $3$ bạn, điểm $7$ có $8$ bạn, điểm $8$ có $6$ bạn, điểm $9$ có $3$ bạn. Số bạn đạt từ $8$ điểm trở lên là:', 'A', 90, null, 'nhap', null, null, null),
  ('C7-B22-M2-Q06', 'C7-B22-M2', 3, 'Muốn biểu diễn sự thay đổi nhiệt độ theo các giờ trong ngày, nên dùng:', 'A', 90, null, 'nhap', null, null, null),
  ('C7-B22-M2-Q07', 'C7-B22-M2', 4, 'Biểu đồ cột cho biết điểm kiểm tra của một nhóm: điểm $6$ có $3$ bạn, điểm $7$ có $8$ bạn, điểm $8$ có $6$ bạn, điểm $9$ có $3$ bạn. Điểm trung bình của nhóm là:', 'A', 120, null, 'nhap', null, null, null),
  ('C7-B22-M2-Q08', 'C7-B22-M2', 4, 'Biểu đồ cột cho biết điểm kiểm tra của một nhóm: điểm $6$ có $3$ bạn, điểm $7$ có $8$ bạn, điểm $8$ có $6$ bạn, điểm $9$ có $3$ bạn. Bạn An kết luận "điểm $9$ có nhiều bạn đạt nhất vì cột điểm $9$ nằm xa nhất bên phải". Nhận xét đúng là:', 'A', 120, null, 'nhap', null, null, null),
  ('C7-B23-M1-Q01', 'C7-B23-M1', 1, 'Trong mẫu có cỡ $N$, giá trị $x$ có tần số $m$. Tần số tương đối của $x$ là:', 'A', 45, null, 'nhap', null, null, null),
  ('C7-B23-M1-Q02', 'C7-B23-M1', 1, 'Tổng các tần số tương đối trong một bảng tần số tương đối bằng:', 'A', 45, null, 'nhap', null, null, null),
  ('C7-B23-M1-Q03', 'C7-B23-M1', 2, 'Lớp có $40$ học sinh, trong đó $10$ bạn thích bóng đá. Tần số tương đối của "thích bóng đá" là:', 'A', 60, null, 'nhap', null, null, null),
  ('C7-B23-M1-Q04', 'C7-B23-M1', 2, 'Mẫu có cỡ $50$, giá trị $A$ có tần số $12$. Tần số tương đối của $A$ là:', 'A', 60, null, 'nhap', null, null, null),
  ('C7-B23-M1-Q05', 'C7-B23-M1', 3, 'Bảng tần số tương đối có các tần số tương đối $20\%$; $35\%$; $x\%$; $15\%$. Giá trị của $x$ là:', 'A', 90, null, 'nhap', null, null, null),
  ('C7-B23-M1-Q06', 'C7-B23-M1', 3, 'Mẫu có cỡ $40$, giá trị $B$ có tần số tương đối $15\%$. Tần số của $B$ là:', 'A', 90, null, 'nhap', null, null, null),
  ('C7-B23-M1-Q07', 'C7-B23-M1', 4, 'Khảo sát $200$ người, có $35\%$ chọn phương án $X$. Số người chọn phương án $X$ là:', 'A', 120, null, 'nhap', null, null, null),
  ('C7-B23-M1-Q08', 'C7-B23-M1', 4, 'Lớp $A$ có $12$ trên $40$ bạn đạt loại giỏi, lớp $B$ có $10$ trên $30$ bạn đạt loại giỏi. Lớp có tỉ lệ học sinh giỏi cao hơn là:', 'A', 120, null, 'nhap', null, null, null),
  ('C7-B23-M2-Q01', 'C7-B23-M2', 1, 'Trong biểu đồ hình quạt tròn, hình quạt biểu diễn tần số tương đối $f\%$ có góc ở tâm bằng:', 'A', 45, null, 'nhap', null, null, null),
  ('C7-B23-M2-Q02', 'C7-B23-M2', 1, 'Trong biểu đồ hình quạt tròn, cả hình tròn biểu diễn:', 'A', 45, null, 'nhap', null, null, null),
  ('C7-B23-M2-Q03', 'C7-B23-M2', 2, 'Một hình quạt biểu diễn $25\%$. Góc ở tâm của hình quạt là:', 'A', 60, null, 'nhap', null, null, null),
  ('C7-B23-M2-Q04', 'C7-B23-M2', 2, 'Một hình quạt có góc ở tâm $72^{\circ}$. Tần số tương đối tương ứng là:', 'A', 60, null, 'nhap', null, null, null),
  ('C7-B23-M2-Q05', 'C7-B23-M2', 3, 'Biểu đồ quạt về phương tiện đến trường của $400$ học sinh: xe đạp $45\%$, đi bộ $25\%$, xe buýt $30\%$. Số học sinh đi xe buýt là:', 'A', 90, null, 'nhap', null, null, null),
  ('C7-B23-M2-Q06', 'C7-B23-M2', 3, 'Biểu đồ quạt về phương tiện đến trường: xe đạp $45\%$, đi bộ $25\%$, xe buýt $30\%$. Góc ở tâm của hình quạt "đi bộ" là:', 'A', 90, null, 'nhap', null, null, null),
  ('C7-B23-M2-Q07', 'C7-B23-M2', 4, 'Muốn so sánh tỉ lệ các phần trong một tổng thể, loại biểu đồ phù hợp nhất là:', 'A', 120, null, 'nhap', null, null, null),
  ('C7-B23-M2-Q08', 'C7-B23-M2', 4, 'Biểu đồ cột tần số tương đối có bốn cột $10\%$, $30\%$, $40\%$ và $x\%$. Bạn Hùng nói $x = 30$. Nhận xét đúng là:', 'A', 120, null, 'nhap', null, null, null),
  ('C7-B24-M1-Q01', 'C7-B24-M1', 1, 'Nhóm số liệu $[a; b)$ gồm các giá trị $x$ thoả mãn:', 'A', 45, null, 'nhap', null, null, null),
  ('C7-B24-M1-Q02', 'C7-B24-M1', 1, 'Độ dài của nhóm $[150; 155)$ là:', 'A', 45, null, 'nhap', null, null, null),
  ('C7-B24-M1-Q03', 'C7-B24-M1', 2, 'Chiều cao $160$ cm thuộc nhóm nào trong các nhóm $[150; 155)$, $[155; 160)$, $[160; 165)$?', 'A', 60, null, 'nhap', null, null, null),
  ('C7-B24-M1-Q04', 'C7-B24-M1', 2, 'Khi nào nên ghép nhóm số liệu?', 'A', 60, null, 'nhap', null, null, null),
  ('C7-B24-M1-Q05', 'C7-B24-M1', 3, 'Giá trị đại diện của nhóm $[20; 30)$ là:', 'A', 90, null, 'nhap', null, null, null),
  ('C7-B24-M1-Q06', 'C7-B24-M1', 3, 'Cân nặng (kg) được chia thành các nhóm $[40; 45)$, $[45; 50)$, $[50; 55)$. Một bạn nặng $45$ kg được xếp vào nhóm:', 'A', 90, null, 'nhap', null, null, null),
  ('C7-B24-M1-Q07', 'C7-B24-M1', 4, 'Thời gian chạy của $30$ học sinh nằm trong khoảng từ $12{,}0$ đến $17{,}9$ giây. Chia thành $6$ nhóm có độ dài bằng nhau, bắt đầu từ $12$. Các nhóm là:', 'A', 120, null, 'nhap', null, null, null),
  ('C7-B24-M1-Q08', 'C7-B24-M1', 4, 'Số liệu: $151$; $158$; $160$; $155$; $162$; $149$; $165$. Số giá trị thuộc nhóm $[155; 160)$ là:', 'A', 120, null, 'nhap', null, null, null),
  ('C7-B24-M2-Q01', 'C7-B24-M2', 1, 'Tần số của nhóm $[a; b)$ là:', 'A', 45, null, 'nhap', null, null, null),
  ('C7-B24-M2-Q02', 'C7-B24-M2', 1, 'Bảng tần số ghép nhóm: $[0; 10)$ có $5$ giá trị; $[10; 20)$ có $12$; $[20; 30)$ có $8$. Cỡ mẫu là:', 'A', 45, null, 'nhap', null, null, null),
  ('C7-B24-M2-Q03', 'C7-B24-M2', 2, 'Điểm thi (thang $10$) của $20$ bạn: $[5; 6)$ có $3$ bạn; $[6; 7)$ có $5$ bạn; $[7; 8)$ có $7$ bạn; $[8; 9)$ có $4$ bạn; $[9; 10]$ có $1$ bạn. Nhóm có tần số lớn nhất là:', 'A', 60, null, 'nhap', null, null, null),
  ('C7-B24-M2-Q04', 'C7-B24-M2', 2, 'Điểm thi (thang $10$) của $20$ bạn: $[5; 6)$ có $3$ bạn; $[6; 7)$ có $5$ bạn; $[7; 8)$ có $7$ bạn; $[8; 9)$ có $4$ bạn; $[9; 10]$ có $1$ bạn. Số bạn đạt từ $8$ điểm trở lên là:', 'A', 60, null, 'nhap', null, null, null),
  ('C7-B24-M2-Q05', 'C7-B24-M2', 3, 'Số liệu: $12$; $15$; $18$; $21$; $22$; $25$; $27$; $29$; $31$; $34$. Tần số của nhóm $[20; 30)$ là:', 'A', 90, null, 'nhap', null, null, null),
  ('C7-B24-M2-Q06', 'C7-B24-M2', 3, 'Bảng tần số ghép nhóm có $4$ nhóm với tần số $6$; $10$; $x$; $4$ và cỡ mẫu $30$. Giá trị của $x$ là:', 'A', 90, null, 'nhap', null, null, null),
  ('C7-B24-M2-Q07', 'C7-B24-M2', 4, 'Điểm thi (thang $10$) của $20$ bạn: $[5; 6)$ có $3$ bạn; $[6; 7)$ có $5$ bạn; $[7; 8)$ có $7$ bạn; $[8; 9)$ có $4$ bạn; $[9; 10]$ có $1$ bạn. Điểm trung bình ước lượng (dùng giá trị đại diện của mỗi nhóm) là:', 'A', 120, null, 'nhap', null, null, null),
  ('C7-B24-M2-Q08', 'C7-B24-M2', 4, 'Khi lập bảng ghép nhóm, bạn Minh đếm giá trị $30$ vào cả nhóm $[20; 30)$ và nhóm $[30; 40)$. Hậu quả là:', 'A', 120, null, 'nhap', null, null, null),
  ('C7-B24-M3-Q01', 'C7-B24-M3', 1, 'Nhóm có tần số $m$ trong mẫu cỡ $N$ thì tần số tương đối của nhóm là:', 'A', 45, null, 'nhap', null, null, null),
  ('C7-B24-M3-Q02', 'C7-B24-M3', 1, 'Nhóm $[10; 20)$ có tần số $8$ trong mẫu cỡ $40$. Tần số tương đối của nhóm là:', 'A', 45, null, 'nhap', null, null, null),
  ('C7-B24-M3-Q03', 'C7-B24-M3', 2, 'Bảng tần số tương đối ghép nhóm: $[0; 2)$ chiếm $15\%$; $[2; 4)$ chiếm $40\%$; $[4; 6)$ chiếm $x\%$; $[6; 8)$ chiếm $10\%$. Giá trị của $x$ là:', 'A', 60, null, 'nhap', null, null, null),
  ('C7-B24-M3-Q04', 'C7-B24-M3', 2, 'Khảo sát thời gian ngủ của $50$ học sinh, nhóm $[7; 8)$ giờ có $20$ bạn. Tần số tương đối của nhóm là:', 'A', 60, null, 'nhap', null, null, null),
  ('C7-B24-M3-Q05', 'C7-B24-M3', 3, 'Mẫu có cỡ $80$, nhóm chiều cao $[150; 160)$ cm có tần số tương đối $25\%$. Số học sinh thuộc nhóm này là:', 'A', 90, null, 'nhap', null, null, null),
  ('C7-B24-M3-Q06', 'C7-B24-M3', 3, 'Bảng tần số tương đối ghép nhóm: $[0; 2)$ chiếm $15\%$; $[2; 4)$ chiếm $40\%$; $[4; 6)$ chiếm $35\%$; $[6; 8)$ chiếm $10\%$. Tỉ lệ số liệu nhỏ hơn $4$ là:', 'A', 90, null, 'nhap', null, null, null),
  ('C7-B24-M3-Q07', 'C7-B24-M3', 4, 'Thời gian dùng điện thoại mỗi ngày của $60$ học sinh: $[0; 1)$ giờ có $9$ bạn; $[1; 2)$ có $24$ bạn; $[2; 3)$ có $18$ bạn; $[3; 4)$ có $9$ bạn. Tần số tương đối của nhóm $[2; 3)$ là:', 'A', 120, null, 'nhap', null, null, null),
  ('C7-B24-M3-Q08', 'C7-B24-M3', 4, 'Thời gian dùng điện thoại mỗi ngày của $60$ học sinh: $[0; 1)$ giờ có $9$ bạn; $[1; 2)$ có $24$ bạn; $[2; 3)$ có $18$ bạn; $[3; 4)$ có $9$ bạn. Tỉ lệ học sinh dùng điện thoại từ $2$ giờ trở lên mỗi ngày là:', 'A', 120, null, 'nhap', null, null, null),
  ('C7-B24-M4-Q01', 'C7-B24-M4', 1, 'Trong biểu đồ cột tần số tương đối ghép nhóm, các cột:', 'A', 45, null, 'nhap', null, null, null),
  ('C7-B24-M4-Q02', 'C7-B24-M4', 1, 'Trong biểu đồ đoạn thẳng tần số tương đối ghép nhóm, mỗi điểm có hoành độ là:', 'A', 45, null, 'nhap', null, null, null),
  ('C7-B24-M4-Q03', 'C7-B24-M4', 2, 'Trong biểu đồ cột ghép nhóm, cột ứng với nhóm $[160; 170)$ cao $30\%$. Ý nghĩa của cột là:', 'A', 60, null, 'nhap', null, null, null),
  ('C7-B24-M4-Q04', 'C7-B24-M4', 2, 'Vẽ biểu đồ đoạn thẳng ghép nhóm với các nhóm $[0; 10)$, $[10; 20)$, $[20; 30)$. Các điểm được đặt tại hoành độ:', 'A', 60, null, 'nhap', null, null, null),
  ('C7-B24-M4-Q05', 'C7-B24-M4', 3, 'Bảng tần số tương đối ghép nhóm: $[0; 2)$ chiếm $15\%$; $[2; 4)$ chiếm $40\%$; $[4; 6)$ chiếm $35\%$; $[6; 8)$ chiếm $10\%$. Nhóm có nhiều số liệu nhất là:', 'A', 90, null, 'nhap', null, null, null),
  ('C7-B24-M4-Q06', 'C7-B24-M4', 3, 'Bảng tần số tương đối ghép nhóm: $[0; 2)$ chiếm $15\%$; $[2; 4)$ chiếm $40\%$; $[4; 6)$ chiếm $35\%$; $[6; 8)$ chiếm $10\%$. Nếu cỡ mẫu là $200$ thì số số liệu thuộc nhóm $[4; 6)$ là:', 'A', 90, null, 'nhap', null, null, null),
  ('C7-B24-M4-Q07', 'C7-B24-M4', 4, 'Một biểu đồ cột tần số tương đối ghép nhóm có các cột tách rời nhau và một cột ghi $120\%$. Nhận xét đúng là:', 'A', 120, null, 'nhap', null, null, null),
  ('C7-B24-M4-Q08', 'C7-B24-M4', 4, 'Để so sánh phân bố chiều cao của hai lớp có sĩ số khác nhau, nên dùng:', 'A', 120, null, 'nhap', null, null, null)
