insert into error_hints (error_code, tier, hint_text) values
  ('E-TS-01', 1, 'Con số em ghi là giá trị (điểm, cỡ giày) hay là số lần giá trị đó xuất hiện?'),
  ('E-TS-01', 2, 'Tần số của một giá trị là số lần giá trị đó xuất hiện trong mẫu. Tổng các tần số bằng cỡ mẫu $N$ (không phải tổng các giá trị). Đếm bằng cách gạch từng số liệu.'),
  ('E-TS-01', 3, 'Ví dụ: $7$; $8$; $7$; $9$; $6$; $7$; $8$; $9$; $7$; $10$ có giá trị $7$ xuất hiện $4$ lần nên tần số của $7$ là $4$.'),
  ('E-TS-02', 1, 'Trục nào ghi giá trị, trục nào ghi tần số? Em đang nhìn chiều cao cột hay vị trí cột?'),
  ('E-TS-02', 2, 'Trục ngang: các giá trị; trục đứng: tần số. Chiều cao cột (hoặc tung độ của điểm) cho biết tần số. Biểu đồ đoạn thẳng hợp với số liệu thay đổi theo thời gian.'),
  ('E-TS-02', 3, 'Ví dụ: cột điểm $7$ cao $8$ nên có $8$ bạn đạt điểm $7$, nhiều nhất trong nhóm.'),
  ('E-TSTD-01', 1, 'Tần số tương đối là tần số chia cho số nào? Em đã nhân $100\%$ chưa?'),
  ('E-TSTD-01', 2, '$f = \dfrac{m}{N} \cdot 100\%$ ($m$ là tần số, $N$ là cỡ mẫu). Tổng các tần số tương đối bằng $100\%$. Ngược lại: $m = f \cdot N$. So sánh hai mẫu cỡ khác nhau thì dùng tần số tương đối.'),
  ('E-TSTD-01', 3, 'Ví dụ: $10$ trên $40$ bạn: $f = \dfrac{10}{40} \cdot 100\% = 25\%$; $35\%$ của $200$ người là $70$ người.'),
  ('E-TSTD-02', 1, 'Cả hình tròn là $360^{\circ}$. Vậy $1\%$ ứng với bao nhiêu độ?'),
  ('E-TSTD-02', 2, 'Góc ở tâm của hình quạt $= f \cdot 360^{\circ}$ (với $f$ viết dạng phần trăm). Ngược lại $f =$ góc : $360^{\circ} \cdot 100\%$. Số người $= f \cdot N$.'),
  ('E-TSTD-02', 3, 'Ví dụ: $25\%$ ứng với $25\% \cdot 360^{\circ} = 90^{\circ}$; góc $72^{\circ}$ ứng với $\dfrac{72}{360} = 20\%$.'),
  ('E-GN-01', 1, 'Nhóm $[a; b)$ có chứa đầu mút $a$ không? Có chứa đầu mút $b$ không?'),
  ('E-GN-01', 2, 'Nhóm $[a; b)$ gồm các $x$ với $a \le x < b$: lấy $a$, không lấy $b$. Mỗi giá trị chỉ thuộc đúng một nhóm. Độ dài nhóm là $b - a$; giá trị đại diện là $(a + b)/2$.'),
  ('E-GN-01', 3, 'Ví dụ: $160$ thuộc nhóm $[160; 165)$, không thuộc $[155; 160)$; nhóm $[20; 30)$ có đại diện $25$.'),
  ('E-GN-02', 1, 'Em đã đếm đúng các số liệu nằm trong nhóm chưa? Khi tính trung bình, mỗi giá trị đại diện được nhân với gì?'),
  ('E-GN-02', 2, 'Tần số nhóm $=$ số số liệu thuộc nhóm. Trung bình ước lượng $=$ (tổng của giá trị đại diện $\times$ tần số) : $N$. Tỉ lệ của nhiều nhóm thì cộng các tần số tương đối.'),
  ('E-GN-02', 3, 'Ví dụ: nhóm $[5; 6)$ đại diện $5{,}5$ có $3$ bạn, … tổng $145 : 20 = 7{,}25$.'),
  ('E-GN-03', 1, 'Các cột của biểu đồ ghép nhóm có khoảng cách không? Điểm của đường gấp khúc đặt ở đâu trong nhóm?'),
  ('E-GN-03', 2, 'Biểu đồ cột ghép nhóm: các cột liền nhau, đáy là nhóm. Biểu đồ đoạn thẳng: nối các điểm (giá trị đại diện; tần số tương đối). Mỗi cột không vượt $100\%$; tổng các cột là $100\%$.'),
  ('E-GN-03', 3, 'Ví dụ: nhóm $[0; 10)$, $[10; 20)$, $[20; 30)$ có điểm đặt tại hoành độ $5$; $15$; $25$.')
on conflict (error_code, tier) do update set hint_text = excluded.hint_text;

insert into micro_lessons (content_id, dan, quy_tac, vi_du, tu_lam) values
  ('VBH-TS-01', 'Giá trị là "cái được đo", tần số là "đếm được bao nhiêu lần". Hai thứ nằm ở hai dòng khác nhau của bảng.', 'Tần số của giá trị $x =$ số lần $x$ xuất hiện. Tổng các tần số $=$ cỡ mẫu $N$.', '[{"de":"$7$; $8$; $7$; $9$; $6$; $7$; $8$; $9$; $7$; $10$: tần số của $7$?","giai":"Cách nghĩ sai: $7$. Cách đúng: $7$ xuất hiện $4$ lần, tần số là $4$."},{"de":"Cỡ giày $36$–$39$ có tần số $3$, $7$, $6$, $4$: số bạn?","giai":"Cộng tần số: $3 + 7 + 6 + 4 = 20$ (không cộng $36 + 37 + 38 + 39$)."}]'::jsonb, '[{"de":"Tần số $5$; $8$; $x$; $7$, $N = 30$: $x$?","dapAn":"$10$","giaiThich":"$30 - 20$.","dapAnGoc":"10"},{"de":"$0$ lỗi: $6$; $1$ lỗi: $7$; $2$: $4$; $3$: $3$. Tổng số lỗi?","dapAn":"$24$","giaiThich":"$0\\cdot 6 + 1\\cdot 7 + 2\\cdot 4 + 3\\cdot 3$.","dapAnGoc":"24"}]'::jsonb),
  ('VBH-TS-02', 'Biểu đồ "nói" bằng chiều cao, không phải bằng vị trí.', 'Trục ngang: giá trị; trục đứng: tần số. Cột cao nhất là giá trị có tần số lớn nhất. Số liệu thay đổi theo thời gian dùng biểu đồ đoạn thẳng.', '[{"de":"Cột điểm $9$ nằm xa nhất bên phải, điểm $9$ nhiều bạn nhất?","giai":"Cách nghĩ sai: đúng. Cách đúng: xem chiều cao: cột điểm $7$ cao $8$ là cao nhất."},{"de":"Điểm $6$: $3$, $7$: $8$, $8$: $6$, $9$: $3$. Từ $8$ trở lên?","giai":"$6 + 3 = 9$ bạn."}]'::jsonb, '[{"de":"Nhiệt độ theo giờ dùng biểu đồ gì?","dapAn":"Đoạn thẳng","giaiThich":"Theo thời gian.","dapAnGoc":"Đoạn thẳng"},{"de":"Chiều cao cột biểu thị gì?","dapAn":"Tần số","giaiThich":"Trục đứng.","dapAnGoc":"Tần số"}]'::jsonb),
  ('VBH-TSTD-01', 'Tần số tương đối trả lời câu hỏi "bao nhiêu phần trăm", để so sánh công bằng giữa các mẫu.', '$f = \dfrac{m}{N} \cdot 100\%$; tổng các $f = 100\%$; ngược lại $m = f \cdot N$.', '[{"de":"$10$ trên $40$ bạn thích bóng đá.","giai":"Cách nghĩ sai: $10\\%$. Cách đúng: $\\dfrac{10}{40} \\cdot 100\\% = 25\\%$."},{"de":"Lớp $A \\dfrac{12}{40}$ giỏi, lớp $B \\dfrac{10}{30}$ giỏi.","giai":"$A$: $30\\%$, $B \\approx 33{,}3\\%$: lớp $B$ tỉ lệ cao hơn dù ít bạn hơn."}]'::jsonb, '[{"de":"$12$ trong $50$?","dapAn":"$24\\%$","giaiThich":"$\\dfrac{12}{50}$.","dapAnGoc":"24%"},{"de":"$15\\%$ của $40$?","dapAn":"$6$","giaiThich":"$0{,}15 \\cdot 40$.","dapAnGoc":"6"}]'::jsonb),
  ('VBH-TSTD-02', 'Biểu đồ quạt: cả hình tròn là $100\%$ và cũng là $360^{\circ}$.', 'Góc ở tâm $= f \cdot 360^{\circ}$. $f =$ góc$/360^{\circ} \cdot 100\%$. Số đối tượng $= f \cdot N$.', '[{"de":"Quạt $25\\%$ có góc bao nhiêu?","giai":"Cách nghĩ sai: $25^{\\circ}$. Cách đúng: $25\\% \\cdot 360^{\\circ} = 90^{\\circ}$."},{"de":"Góc $72^{\\circ}$ ứng với bao nhiêu phần trăm?","giai":"$\\dfrac{72}{360} = 20\\%$."}]'::jsonb, '[{"de":"$30\\%$ của $400$ học sinh?","dapAn":"$120$","giaiThich":"$0{,}3 \\cdot 400$.","dapAnGoc":"120"},{"de":"$10\\%$ có góc?","dapAn":"$36^{\\circ}$","giaiThich":"$0{,}1 \\cdot 360^{\\circ}$.","dapAnGoc":"36°"}]'::jsonb),
  ('VBH-GN-01', 'Nhóm $[a; b)$ có "cửa trái mở, cửa phải đóng": nhận $a$, không nhận $b$.', '$[a; b)$ gồm $a \le x < b$. Mỗi số liệu thuộc đúng một nhóm. Độ dài nhóm $b - a$; giá trị đại diện $(a + b)/2$.', '[{"de":"$160$ thuộc $[155; 160)$ hay $[160; 165)$?","giai":"Cách nghĩ sai: $[155; 160)$. Cách đúng: $[155; 160)$ không lấy $160$, nên $160$ thuộc $[160; 165)$."},{"de":"Đại diện của $[20; 30)$?","giai":"$(20 + 30)/2 = 25$."}]'::jsonb, '[{"de":"$45$ kg thuộc $[40; 45)$ hay $[45; 50)$?","dapAn":"$[45; 50)$","giaiThich":"Lấy đầu mút trái.","dapAnGoc":"[45; 50)"},{"de":"Độ dài $[150; 155)$?","dapAn":"$5$","giaiThich":"$155 - 150$.","dapAnGoc":"5"}]'::jsonb),
  ('VBH-GN-02', 'Có bảng ghép nhóm rồi, mọi câu hỏi "bao nhiêu", "trung bình" đều tính từ tần số và giá trị đại diện.', 'Tần số nhóm $=$ số số liệu trong nhóm. Trung bình ước lượng $= \Sigma$(đại diện $\times$ tần số) : $N$. Tỉ lệ nhiều nhóm $=$ cộng các tần số tương đối.', '[{"de":"$[5; 6)$: $3$, $[6; 7)$: $5$, $[7; 8)$: $7$, $[8; 9)$: $4$, $[9; 10]$: $1$. Trung bình?","giai":"Cách nghĩ sai: $(5{,}5 + 6{,}5 + 7{,}5 + 8{,}5 + 9{,}5) : 5 = 7{,}5$. Cách đúng: $(16{,}5 + 32{,}5 + 52{,}5 + 34 + 9{,}5) : 20 = 7{,}25$."},{"de":"Tỉ lệ số liệu nhỏ hơn $4$ khi $[0; 2) 15\\%$, $[2; 4) 40\\%$?","giai":"$15\\% + 40\\% = 55\\%$."}]'::jsonb, '[{"de":"$12$; $15$; $18$; $21$; $22$; $25$; $27$; $29$; $31$; $34$: tần số $[20; 30)$?","dapAn":"$5$","giaiThich":"$21$, $22$, $25$, $27$, $29$.","dapAnGoc":"5"},{"de":"Tần số $6$; $10$; $x$; $4$, $N = 30$: $x$?","dapAn":"$10$","giaiThich":"$30 - 20$.","dapAnGoc":"10"}]'::jsonb),
  ('VBH-GN-03', 'Biểu đồ ghép nhóm khác biểu đồ thường ở hai chi tiết: cột liền nhau, điểm đặt ở giữa nhóm.', 'Biểu đồ cột ghép nhóm: các cột liền nhau, mỗi cột là một nhóm. Biểu đồ đoạn thẳng: điểm (giá trị đại diện; tần số tương đối). Tổng các cột tần số tương đối là $100\%$.', '[{"de":"Đặt điểm của nhóm $[0; 10)$ tại đâu?","giai":"Cách nghĩ sai: hoành độ $0$. Cách đúng: hoành độ $5$ (trung điểm)."},{"de":"So sánh hai lớp sĩ số khác nhau.","giai":"Dùng tần số tương đối, không dùng số bạn."}]'::jsonb, '[{"de":"Cột $[160; 170)$ cao $30\\%$ nghĩa là?","dapAn":"$30\\%$ số liệu từ $160$ đến dưới $170$","giaiThich":"Tần số tương đối.","dapAnGoc":"30% số liệu từ 160 đến dưới 170"},{"de":"Cột ghi $120\\%$ có hợp lí?","dapAn":"Không","giaiThich":"Không vượt $100\\%$.","dapAnGoc":"Không"}]'::jsonb)
on conflict (content_id) do update set dan = excluded.dan, quy_tac = excluded.quy_tac,
  vi_du = excluded.vi_du, tu_lam = excluded.tu_lam, updated_at = now();

