-- Link video: chỉ điền khi ô còn trống — link giáo viên đã tự gắn ở /gv/noi-dung được giữ nguyên.
on conflict (content_id) do update set title = excluded.title, ku_id = excluded.ku_id,
  duration_sec = case when contents.url is null or contents.url = '' then excluded.duration_sec else contents.duration_sec end,
  nguon = case when contents.url is null or contents.url = '' then excluded.nguon else contents.nguon end,
  url = case when contents.url is null or contents.url = '' then excluded.url else contents.url end;

insert into error_dictionary (error_code, ku_id, misconception, remediation_id) values
  ('E-XS-01', 'C8-B25-M1', 'Liệt kê không gian mẫu thiếu hoặc thừa kết quả, gộp các kết quả có thứ tự khác nhau (SN với NS) thành một. Ví dụ: Tung đồng xu hai lần: Ω = {SS; SN; NN}', 'VBH-XS-01'),
  ('E-XS-02', 'C8-B26-M1', 'Liệt kê kết quả thuận lợi có cả giá trị nằm ngoài không gian mẫu, bỏ sót kết quả, hoặc hiểu sai điều kiện của biến cố. Ví dụ: Số nguyên tố trên xúc xắc: 1; 2; 3; 5', 'VBH-XS-02'),
  ('E-XS-03', 'C8-B26-M2', 'Lấy số kết quả thuận lợi làm xác suất, chia cho số loại thay vì số kết quả, hoặc ra xác suất lớn hơn 1. Ví dụ: 3 bi đỏ, 5 xanh, 2 vàng: P(không xanh) = 1/3', 'VBH-XS-03'),
  ('E-XS-04', 'C8-B25-M1', 'Đếm số phần tử của không gian mẫu khi gieo hai xúc xắc, lấy lần lượt có/không hoàn lại, lấy đồng thời sai. Ví dụ: Gieo hai xúc xắc có 12 kết quả', 'VBH-XS-04')
on conflict (error_code) do update set ku_id = excluded.ku_id, misconception = excluded.misconception,
  remediation_id = excluded.remediation_id;

insert into questions (question_id, ku_id, level, stem, correct_option, expected_time_sec, hinh, trang_thai, ghi_chu_gv, nguoi_duyet, ngay_duyet) values
  ('C8-B25-M1-Q01', 'C8-B25-M1', 1, 'Gieo một con xúc xắc $6$ mặt. Không gian mẫu là:', 'A', 45, null, 'nhap', null, null, null),
  ('C8-B25-M1-Q02', 'C8-B25-M1', 1, 'Tung một đồng xu hai lần liên tiếp. Không gian mẫu có số phần tử là:', 'A', 45, null, 'nhap', null, null, null),
  ('C8-B25-M1-Q03', 'C8-B25-M1', 2, 'Tung một đồng xu hai lần liên tiếp. Không gian mẫu là:', 'A', 60, null, 'nhap', null, null, null),
  ('C8-B25-M1-Q04', 'C8-B25-M1', 2, 'Rút ngẫu nhiên $1$ thẻ từ $10$ thẻ đánh số $1$; $2$; …; $10$. Không gian mẫu có số phần tử là:', 'A', 60, null, 'nhap', null, null, null),
  ('C8-B25-M1-Q05', 'C8-B25-M1', 3, 'Gieo đồng thời hai con xúc xắc (một xanh, một đỏ). Không gian mẫu có số phần tử là:', 'A', 90, null, 'nhap', null, null, null),
  ('C8-B25-M1-Q06', 'C8-B25-M1', 3, 'Hộp có $1$ bi xanh, $1$ bi đỏ, $1$ bi vàng. Lấy lần lượt $2$ viên, không hoàn lại. Không gian mẫu có số phần tử là:', 'A', 90, null, 'nhap', null, null, null),
  ('C8-B25-M1-Q07', 'C8-B25-M1', 4, 'Bạn An chọn ngẫu nhiên một ngày trong tuần và một buổi (sáng hoặc chiều) để đi bơi. Không gian mẫu có số phần tử là:', 'A', 120, null, 'nhap', null, null, null),
  ('C8-B25-M1-Q08', 'C8-B25-M1', 4, 'Túi có $2$ bi đỏ Đ$1$, Đ$2$ và $1$ bi xanh $X$. Lấy ngẫu nhiên đồng thời $2$ viên. Không gian mẫu là:', 'A', 120, null, 'nhap', null, null, null),
  ('C8-B26-M1-Q01', 'C8-B26-M1', 1, 'Gieo một con xúc xắc. Các kết quả thuận lợi cho biến cố "Mặt xuất hiện có số chấm chẵn" là:', 'A', 45, null, 'nhap', null, null, null),
  ('C8-B26-M1-Q02', 'C8-B26-M1', 1, 'Rút $1$ thẻ từ $10$ thẻ đánh số $1$ đến $10$. Các kết quả thuận lợi cho biến cố "Số trên thẻ chia hết cho $3$" là:', 'A', 45, null, 'nhap', null, null, null),
  ('C8-B26-M1-Q03', 'C8-B26-M1', 2, 'Gieo một con xúc xắc. Số kết quả thuận lợi cho biến cố "Số chấm xuất hiện là số nguyên tố" là:', 'A', 60, null, 'nhap', null, null, null),
  ('C8-B26-M1-Q04', 'C8-B26-M1', 2, 'Tung một đồng xu hai lần. Các kết quả thuận lợi cho biến cố "Có đúng một lần xuất hiện mặt ngửa" là:', 'A', 60, null, 'nhap', null, null, null),
  ('C8-B26-M1-Q05', 'C8-B26-M1', 3, 'Gieo hai con xúc xắc. Số kết quả thuận lợi cho biến cố "Tổng số chấm bằng $7$" là:', 'A', 90, null, 'nhap', null, null, null),
  ('C8-B26-M1-Q06', 'C8-B26-M1', 3, 'Gieo hai con xúc xắc. Số kết quả thuận lợi cho biến cố "Hai mặt có số chấm bằng nhau" là:', 'A', 90, null, 'nhap', null, null, null),
  ('C8-B26-M1-Q07', 'C8-B26-M1', 4, 'Rút $1$ thẻ từ $10$ thẻ đánh số $1$ đến $10$. Biến cố "Số trên thẻ lớn hơn $10$" là:', 'A', 120, null, 'nhap', null, null, null),
  ('C8-B26-M1-Q08', 'C8-B26-M1', 4, 'Lớp có $15$ bạn nam và $20$ bạn nữ. Chọn ngẫu nhiên $1$ bạn làm lớp trưởng. Số kết quả thuận lợi cho biến cố "Chọn được bạn nữ" là:', 'A', 120, null, 'nhap', null, null, null),
  ('C8-B26-M2-Q01', 'C8-B26-M2', 1, 'Gieo một con xúc xắc cân đối. Xác suất xuất hiện mặt $6$ chấm là:', 'A', 45, null, 'nhap', null, null, null),
  ('C8-B26-M2-Q02', 'C8-B26-M2', 1, 'Xác suất của một biến cố là một số:', 'A', 45, null, 'nhap', null, null, null),
  ('C8-B26-M2-Q03', 'C8-B26-M2', 2, 'Gieo một con xúc xắc cân đối. Xác suất xuất hiện mặt có số chấm chẵn là:', 'A', 60, null, 'nhap', null, null, null),
  ('C8-B26-M2-Q04', 'C8-B26-M2', 2, 'Rút $1$ thẻ từ $10$ thẻ đánh số $1$ đến $10$. Xác suất rút được thẻ ghi số chia hết cho $3$ là:', 'A', 60, null, 'nhap', null, null, null),
  ('C8-B26-M2-Q05', 'C8-B26-M2', 3, 'Tung một đồng xu cân đối hai lần. Xác suất cả hai lần đều xuất hiện mặt ngửa là:', 'A', 90, null, 'nhap', null, null, null),
  ('C8-B26-M2-Q06', 'C8-B26-M2', 3, 'Gieo hai con xúc xắc cân đối. Xác suất tổng số chấm bằng $7$ là:', 'A', 90, null, 'nhap', null, null, null),
  ('C8-B26-M2-Q07', 'C8-B26-M2', 4, 'Hộp có $3$ bi đỏ, $5$ bi xanh và $2$ bi vàng. Lấy ngẫu nhiên $1$ viên. Xác suất lấy được viên bi không phải màu xanh là:', 'A', 120, null, 'nhap', null, null, null),
  ('C8-B26-M2-Q08', 'C8-B26-M2', 4, 'Rút ngẫu nhiên $1$ thẻ từ $10$ thẻ đánh số $1$ đến $10$. Xác suất để tổng các số trên $9$ thẻ còn lại chia hết cho $3$ là:', 'A', 120, null, 'nhap', null, null, null)
