insert into error_hints (error_code, tier, hint_text) values
  ('E-XS-01', 1, 'Em đã liệt kê hết các kết quả có thể chưa? $SN$ và $NS$ có phải cùng một kết quả không?'),
  ('E-XS-01', 2, 'Không gian mẫu $\Omega$ là tập hợp tất cả các kết quả có thể, mỗi kết quả liệt kê đúng một lần. Phép thử nhiều bước thì ghi kết quả theo thứ tự từng bước (dùng bảng hoặc sơ đồ cây).'),
  ('E-XS-01', 3, 'Ví dụ: tung đồng xu hai lần: $\Omega = \{SS; SN; NS; NN\}$, có $4$ phần tử.'),
  ('E-XS-02', 1, 'Kết quả em chọn có nằm trong không gian mẫu không? Nó có làm biến cố xảy ra không?'),
  ('E-XS-02', 2, 'Kết quả thuận lợi cho $A$ là các phần tử của $\Omega$ mà khi xảy ra thì $A$ xảy ra. Kiểm tra từng phần tử của $\Omega$. Biến cố không có kết quả thuận lợi nào là biến cố không thể.'),
  ('E-XS-02', 3, 'Ví dụ: xúc xắc, biến cố "số nguyên tố": $2$; $3$; $5$ (số $1$ không phải số nguyên tố).'),
  ('E-XS-03', 1, 'Em đã chia số kết quả thuận lợi cho tổng số kết quả của không gian mẫu chưa?'),
  ('E-XS-03', 2, 'Khi các kết quả đồng khả năng: $P(A) = n(A) : n(\Omega )$, luôn từ $0$ đến $1$. Đếm theo từng kết quả (từng viên bi), không theo số loại (số màu).'),
  ('E-XS-03', 3, 'Ví dụ: $3$ đỏ, $5$ xanh, $2$ vàng: $P$(không xanh) $= (3 + 2) : 10 = \dfrac{1}{2}$.'),
  ('E-XS-04', 1, 'Phép thử có mấy bước? Mỗi bước có bao nhiêu khả năng? Lấy xong có trả lại không?'),
  ('E-XS-04', 2, 'Phép thử nhiều bước: số kết quả $=$ tích số khả năng mỗi bước (lập bảng). Lấy lần lượt không hoàn lại thì bước sau ít hơn một khả năng; lấy đồng thời thì không xét thứ tự.'),
  ('E-XS-04', 3, 'Ví dụ: gieo hai xúc xắc: $6 \cdot 6 = 36$ kết quả; $3$ bi lấy lần lượt $2$ viên không hoàn lại: $3 \cdot 2 = 6$ kết quả.')
on conflict (error_code, tier) do update set hint_text = excluded.hint_text;

insert into micro_lessons (content_id, dan, quy_tac, vi_du, tu_lam) values
  ('VBH-XS-01', 'Xác suất đúng hay sai phụ thuộc trước hết vào việc liệt kê đủ không gian mẫu.', '$\Omega$ gồm mọi kết quả có thể, mỗi kết quả một lần. Phép thử hai bước: viết kết quả theo thứ tự (lần $1$, lần $2$); $SN$ khác $NS$.', '[{"de":"Tung đồng xu hai lần, viết $\\Omega$.","giai":"Cách nghĩ sai: $\\{SS; SN; NN\\}$. Cách đúng: $\\{SS; SN; NS; NN\\}$, vì \"sấp rồi ngửa\" khác \"ngửa rồi sấp\"."},{"de":"Rút $1$ thẻ từ thẻ số $1$ đến $10$.","giai":"$\\Omega =$ {$1; 2$; …; $10$}, có $10$ phần tử."}]'::jsonb, '[{"de":"Gieo xúc xắc, $n(\\Omega )$?","dapAn":"$6$","giaiThich":"$1$ đến $6$.","dapAnGoc":"6"},{"de":"Tung đồng xu $3$ lần, $n(\\Omega )$?","dapAn":"$8$","giaiThich":"$2 \\cdot 2 \\cdot 2$.","dapAnGoc":"8"}]'::jsonb),
  ('VBH-XS-02', 'Kết quả thuận lợi phải "đến từ" không gian mẫu và làm biến cố xảy ra.', 'Duyệt từng phần tử của $\Omega$, giữ lại phần tử làm $A$ xảy ra. Không có phần tử nào: biến cố không thể; mọi phần tử: biến cố chắc chắn.', '[{"de":"Xúc xắc, biến cố \"số nguyên tố\".","giai":"Cách nghĩ sai: $1$; $2$; $3$; $5$. Cách đúng: $1$ không là số nguyên tố, kết quả thuận lợi là $2$; $3$; $5$."},{"de":"Hai xúc xắc, tổng $7$.","giai":"$(1;6)$, $(2;5)$, $(3;4)$, $(4;3)$, $(5;2)$, $(6;1)$: $6$ kết quả."}]'::jsonb, '[{"de":"Thẻ $1$–$10$ chia hết cho $3$?","dapAn":"$3$; $6$; $9$","giaiThich":"Trong $\\Omega$.","dapAnGoc":"3; 6; 9"},{"de":"Thẻ $1$–$10$ lớn hơn $10$?","dapAn":"Không có (biến cố không thể)","giaiThich":"Không phần tử nào.","dapAnGoc":"Không có (biến cố không thể)"}]'::jsonb),
  ('VBH-XS-03', 'Xác suất là một tỉ số — luôn nằm giữa $0$ và $1$.', '$P(A) = n(A) : n(\Omega )$ khi các kết quả đồng khả năng. Đếm theo từng kết quả, không theo số loại.', '[{"de":"$3$ đỏ, $5$ xanh, $2$ vàng, $P$(không xanh)?","giai":"Cách nghĩ sai: $2$ màu trên $3$ màu nên $\\dfrac{2}{3}$, hoặc $\\dfrac{1}{3}$. Cách đúng: $5$ viên không xanh trên $10$ viên: $\\dfrac{1}{2}$."},{"de":"Xúc xắc, $P$(chẵn)?","giai":"$\\dfrac{3}{6} = \\dfrac{1}{2}$."}]'::jsonb, '[{"de":"$P$(mặt $6$)?","dapAn":"$\\dfrac{1}{6}$","giaiThich":"$1 : 6$.","dapAnGoc":"1/6"},{"de":"Thẻ $1$–$10$, $P$(chia hết cho $3$)?","dapAn":"$\\dfrac{3}{10}$","giaiThich":"$3 : 10$.","dapAnGoc":"3/10"}]'::jsonb),
  ('VBH-XS-04', 'Phép thử có nhiều bước thì "nhân" số khả năng, và để ý có trả lại hay không.', 'Số kết quả $=$ tích số khả năng mỗi bước. Không hoàn lại: bước sau giảm $1$. Lấy đồng thời: không phân biệt thứ tự.', '[{"de":"Gieo hai xúc xắc, $n(\\Omega )$?","giai":"Cách nghĩ sai: $6 + 6 = 12$. Cách đúng: $6 \\cdot 6 = 36$ (lập bảng $6 \\times 6$)."},{"de":"$3$ bi khác màu, lấy lần lượt $2$ viên không hoàn lại.","giai":"$3 \\cdot 2 = 6$ kết quả có thứ tự."}]'::jsonb, '[{"de":"$7$ ngày, $2$ buổi?","dapAn":"$14$","giaiThich":"$7 \\cdot 2$.","dapAnGoc":"14"},{"de":"$3$ bi, lấy đồng thời $2$ viên?","dapAn":"$3$","giaiThich":"Không xét thứ tự.","dapAnGoc":"3"}]'::jsonb)
on conflict (content_id) do update set dan = excluded.dan, quy_tac = excluded.quy_tac,
  vi_du = excluded.vi_du, tu_lam = excluded.tu_lam, updated_at = now();

