on conflict (content_id) do update set title = excluded.title, ku_id = excluded.ku_id,
  duration_sec = case when contents.url is null or contents.url = '' then excluded.duration_sec else contents.duration_sec end,
  nguon = case when contents.url is null or contents.url = '' then excluded.nguon else contents.nguon end,
  url = case when contents.url is null or contents.url = '' then excluded.url else contents.url end;

insert into error_dictionary (error_code, ku_id, misconception, remediation_id) values
  ('E-GNT-01', 'C9-B27-M1', 'Cho góc nội tiếp bằng số đo cung bị chắn (quên chia đôi) hoặc nhầm góc nội tiếp với góc ở tâm. Ví dụ: Góc nội tiếp chắn cung 80° có số đo 80°', 'VBH-GNT-01'),
  ('E-GNT-02', 'C9-B27-M1', 'Không dùng được hệ quả: góc nội tiếp chắn nửa đường tròn là 90°, các góc nội tiếp cùng chắn một cung bằng nhau. Ví dụ: AB là đường kính nhưng không biết góc ACB = 90°', 'VBH-GNT-02'),
  ('E-NTT-01', 'C9-B28-M1', 'Cho tâm đường tròn ngoại tiếp là giao các đường phân giác, trung tuyến hoặc đường cao. Ví dụ: Tâm ngoại tiếp là trọng tâm tam giác', 'VBH-NTT-01'),
  ('E-NTT-02', 'C9-B28-M2', 'Lấy bán kính ngoại tiếp tam giác vuông bằng cạnh huyền, nhầm a√3/3 với a√3/6 hoặc a√3/2. Ví dụ: Tam giác đều cạnh 6: R = 3√3', 'VBH-NTT-02'),
  ('E-NTT-03', 'C9-B28-M3', 'Cho tâm đường tròn nội tiếp là giao các đường trung trực, hoặc nhầm "cách đều ba cạnh" với "cách đều ba đỉnh". Ví dụ: Vòi phun cách đều ba bờ rào đặt ở giao ba đường trung trực', 'VBH-NTT-03'),
  ('E-TGNT-01', 'C9-B29-M1', 'Cho hai góc kề hoặc hai góc đối của tứ giác nội tiếp bằng nhau, hoặc tổng hai góc đối bằng 360°. Ví dụ: Tứ giác nội tiếp có góc A = 70° thì góc C = 70°', 'VBH-TGNT-01'),
  ('E-TGNT-02', 'C9-B29-M2', 'Cho hình thoi, hình bình hành luôn nội tiếp được, hoặc lấy bán kính bằng cạnh, bằng đường chéo. Ví dụ: Hình vuông cạnh 4 nội tiếp đường tròn bán kính 4', 'VBH-TGNT-02'),
  ('E-DGD-01', 'C9-B30-M1', 'Cho hình thoi (chỉ cạnh bằng nhau) hoặc hình chữ nhật (chỉ góc bằng nhau) là đa giác đều; nhầm đa giác lồi với đa giác lõm. Ví dụ: Hình thoi là đa giác đều', 'VBH-DGD-01'),
  ('E-DGD-02', 'C9-B30-M2', 'Dùng sai công thức tổng các góc trong (n·180°, 360°), hoặc quên chia cho n khi tính mỗi góc của đa giác đều. Ví dụ: Mỗi góc của lục giác đều là 720°', 'VBH-DGD-02'),
  ('E-PQ-01', 'C9-B30-M3', 'Nhầm phép quay với phép đối xứng hoặc phép tịnh tiến, sai chiều quay, sai góc khi đổi thời gian ra độ. Ví dụ: Phép quay 90° biến A(2; 0) thành (0; −2) khi quay ngược chiều kim đồng hồ', 'VBH-PQ-01'),
  ('E-PQ-02', 'C9-B30-M4', 'Lấy góc trong của đa giác làm góc quay, hoặc chia 360° cho số sai. Ví dụ: Phép quay 108° giữ nguyên ngũ giác đều', 'VBH-PQ-02')
on conflict (error_code) do update set ku_id = excluded.ku_id, misconception = excluded.misconception,
  remediation_id = excluded.remediation_id;

insert into questions (question_id, ku_id, level, stem, correct_option, expected_time_sec, hinh, trang_thai, ghi_chu_gv, nguoi_duyet, ngay_duyet) values
  ('C9-B27-M1-Q01', 'C9-B27-M1', 1, 'Góc nội tiếp là góc:', 'A', 45, null, 'nhap', null, null, null),
  ('C9-B27-M1-Q02', 'C9-B27-M1', 1, 'Góc nội tiếp chắn cung có số đo $80^{\circ}$ thì có số đo là:', 'A', 45, null, 'nhap', null, null, null),
  ('C9-B27-M1-Q03', 'C9-B27-M1', 2, 'Góc nội tiếp $BAC = 35^{\circ}$. Số đo cung $BC$ bị chắn là:', 'A', 60, null, 'nhap', null, null, null),
  ('C9-B27-M1-Q04', 'C9-B27-M1', 2, 'Góc nội tiếp chắn nửa đường tròn có số đo là:', 'A', 60, null, 'nhap', null, null, null),
  ('C9-B27-M1-Q05', 'C9-B27-M1', 3, 'Cho $(O)$, góc ở tâm $AOB = 100^{\circ}$, điểm $C$ thuộc cung lớn $AB$. Số đo góc $ACB$ là:', 'A', 90, null, 'nhap', null, null, null),
  ('C9-B27-M1-Q06', 'C9-B27-M1', 3, 'Cho $(O)$ đường kính $AB$, điểm $C$ thuộc đường tròn (khác $A$, $B$), góc $CAB = 30^{\circ}$. Số đo góc $CBA$ là:', 'A', 90, null, 'nhap', null, null, null),
  ('C9-B27-M1-Q07', 'C9-B27-M1', 4, 'Hai góc nội tiếp $ACB$ và $ADB$ cùng chắn cung $AB$ ($C$, $D$ nằm cùng phía đối với $AB$). Biết góc $ACB = 42^{\circ}$, số đo góc $ADB$ là:', 'A', 120, null, 'nhap', null, null, null),
