insert into error_hints (error_code, tier, hint_text) values
  ('E-GNT-01', 1, 'Đỉnh của góc nằm ở tâm hay trên đường tròn? Góc nội tiếp bằng cả cung hay một nửa cung?'),
  ('E-GNT-01', 2, 'Góc nội tiếp có đỉnh trên đường tròn và bằng NỬA số đo cung bị chắn. Góc ở tâm (đỉnh là tâm) mới bằng cả số đo cung.'),
  ('E-GNT-01', 3, 'Ví dụ: góc nội tiếp chắn cung $80^{\circ}$ có số đo $40^{\circ}$; góc $AOB = 100^{\circ}$ thì góc nội tiếp $ACB$ chắn cung đó bằng $50^{\circ}$.'),
  ('E-GNT-02', 1, 'Cung bị chắn có phải nửa đường tròn không? Hai góc có cùng chắn một cung không?'),
  ('E-GNT-02', 2, 'Góc nội tiếp chắn nửa đường tròn là góc vuông. Các góc nội tiếp cùng chắn một cung (hoặc chắn các cung bằng nhau) thì bằng nhau.'),
  ('E-GNT-02', 3, 'Ví dụ: $AB$ là đường kính, $C$ thuộc đường tròn thì góc $ACB = 90^{\circ}$; góc $CAB = 30^{\circ}$ thì góc $CBA = 60^{\circ}$.'),
  ('E-NTT-01', 1, 'Tâm đường tròn ngoại tiếp phải cách đều cái gì: ba đỉnh hay ba cạnh?'),
  ('E-NTT-01', 2, 'Tâm đường tròn ngoại tiếp cách đều ba đỉnh, là giao điểm ba đường trung trực (chỉ cần vẽ hai). Tam giác nhọn: tâm ở trong; vuông: ở trung điểm cạnh huyền; tù: ở ngoài tam giác.'),
  ('E-NTT-01', 3, 'Ví dụ: trạm phát sóng cách đều ba ngôi nhà đặt tại giao điểm các đường trung trực.'),
  ('E-NTT-02', 1, 'Tam giác là tam giác vuông hay tam giác đều? Cạnh huyền là đường kính hay bán kính?'),
  ('E-NTT-02', 2, 'Tam giác vuông: $R =$ cạnh huyền : $2$. Tam giác đều cạnh $a$: $R = a\sqrt{3}/3$ (bằng $\dfrac{2}{3}$ đường cao), $r = a\sqrt{3}/6$ (bằng $\dfrac{1}{3}$ đường cao).'),
  ('E-NTT-02', 3, 'Ví dụ: tam giác đều cạnh $6$: đường cao $3\sqrt{3}$, $R = 2\sqrt{3}$, $r = \sqrt{3}$; tam giác vuông cạnh $6$, $8$, $10$ có $R = 5$.'),
  ('E-NTT-03', 1, 'Tâm đường tròn nội tiếp cách đều ba đỉnh hay ba cạnh?'),
  ('E-NTT-03', 2, 'Tâm đường tròn nội tiếp là giao điểm ba đường phân giác trong, cách đều ba cạnh và luôn nằm trong tam giác. Tam giác vuông: $r = (b + c - a)/2$.'),
  ('E-NTT-03', 3, 'Ví dụ: vòi phun cách đều ba bờ rào đặt tại giao ba đường phân giác; tam giác $6$, $8$, $10$ có $r = (6 + 8 - 10)/2 = 2$.'),
  ('E-TGNT-01', 1, 'Hai góc em đang xét là hai góc đối (không chung cạnh) hay hai góc kề?'),
  ('E-TGNT-01', 2, 'Tứ giác nội tiếp $\Leftrightarrow$ tổng hai góc đối bằng $180^{\circ}$. Góc ngoài tại một đỉnh bằng góc trong của đỉnh đối diện. Hai góc vuông cùng nhìn một đoạn thì bốn điểm cùng thuộc đường tròn.'),
  ('E-TGNT-01', 3, 'Ví dụ: góc $A = 70^{\circ}$ thì góc $C = 110^{\circ}$; góc ngoài tại $C$ bằng $75^{\circ}$ thì góc $A = 75^{\circ}$.'),
  ('E-TGNT-02', 1, 'Hình đó có tổng hai góc đối bằng $180^{\circ}$ không? Bán kính bằng cạnh hay bằng nửa đường chéo?'),
  ('E-TGNT-02', 2, 'Hình chữ nhật, hình vuông nội tiếp đường tròn tâm là giao hai đường chéo, $R =$ đường chéo : $2$. Hình vuông cạnh $a$: $R = a\sqrt{2}/2$; ngược lại cạnh $= R\sqrt{2}$. Hình thoi, hình bình hành (không phải chữ nhật) không nội tiếp được.'),
  ('E-TGNT-02', 3, 'Ví dụ: hình chữ nhật $6 \times 8$ có đường chéo $10$, $R = 5$.'),
  ('E-DGD-01', 1, 'Đa giác đều cần những gì bằng nhau: chỉ cạnh, chỉ góc, hay cả hai?'),
  ('E-DGD-01', 2, 'Đa giác đều: đa giác lồi có mọi cạnh bằng nhau VÀ mọi góc bằng nhau. Hình thoi chỉ có cạnh bằng nhau, hình chữ nhật chỉ có góc bằng nhau. Số đường chéo của đa giác $n$ cạnh là $n(n - 3)/2$.'),
  ('E-DGD-01', 3, 'Ví dụ: hình vuông là đa giác đều; hình thoi góc $60^{\circ}$ không phải.'),
  ('E-DGD-02', 1, 'Tổng các góc trong của đa giác $n$ cạnh là bao nhiêu? Đa giác đều có mấy góc bằng nhau?'),
  ('E-DGD-02', 2, 'Tổng góc trong $= (n - 2)\cdot 180^{\circ}$. Mỗi góc của đa giác đều $= (n - 2)\cdot 180^{\circ}/n$. Mỗi góc ngoài $= 360^{\circ}/n$; tổng các góc ngoài $= 360^{\circ}$.'),
  ('E-DGD-02', 3, 'Ví dụ: lục giác đều: $(6 - 2)\cdot 180^{\circ}/6 = 120^{\circ}$; góc trong $150^{\circ}$ thì góc ngoài $30^{\circ}$, số cạnh $360 : 30 = 12$.'),
  ('E-PQ-01', 1, 'Sau phép quay, khoảng cách từ điểm đến tâm có thay đổi không? Quay theo chiều nào?'),
  ('E-PQ-01', 2, 'Phép quay tâm $O$ góc $\alpha$: $OA'' = OA$ và góc $AOA'' = \alpha$ theo chiều đã cho (chiều dương là ngược chiều kim đồng hồ). Tâm $O$ đứng yên. Một vòng $= 360^{\circ}$; kim phút quay $6^{\circ}$ mỗi phút.'),
  ('E-PQ-01', 3, 'Ví dụ: quay $90^{\circ}$ ngược chiều kim đồng hồ quanh $O$, $A(2; 0)$ đến $(0; 2)$; $15$ phút kim phút quay $90^{\circ}$.'),
  ('E-PQ-02', 1, 'Chia $360^{\circ}$ cho số cạnh của đa giác thì được góc nào?'),
  ('E-PQ-02', 2, 'Phép quay tâm $O$ giữ nguyên đa giác đều $n$ cạnh tâm $O$ có góc $k\cdot 360^{\circ}/n$ ($k = 1$, $2$, …, $n$). Đó là góc ở tâm, không phải góc trong của đa giác.'),
  ('E-PQ-02', 3, 'Ví dụ: ngũ giác đều: $72^{\circ}$, $144^{\circ}$, $216^{\circ}$, $288^{\circ}$, $360^{\circ}$; không phải $108^{\circ}$ (góc trong).')
on conflict (error_code, tier) do update set hint_text = excluded.hint_text;

insert into micro_lessons (content_id, dan, quy_tac, vi_du, tu_lam) values
  ('VBH-GNT-01', 'Góc ở tâm "thấy" trọn cung, góc nội tiếp đứng xa hơn nên chỉ "thấy" một nửa.', 'Góc nội tiếp $= \dfrac{1}{2}$ số đo cung bị chắn $= \dfrac{1}{2}$ góc ở tâm cùng chắn cung đó.', '[{"de":"Góc nội tiếp chắn cung $80^{\\circ}$.","giai":"Cách nghĩ sai: $80^{\\circ}$. Cách đúng: $80^{\\circ} : 2 = 40^{\\circ}$."},{"de":"Góc nội tiếp $BAC = 35^{\\circ}$, cung $BC$?","giai":"Cung $BC = 2 \\cdot 35^{\\circ} = 70^{\\circ}$."}]'::jsonb, '[{"de":"Góc $AOB = 100^{\\circ}$, góc nội tiếp $ACB$ chắn cung đó?","dapAn":"$50^{\\circ}$","giaiThich":"Nửa góc ở tâm.","dapAnGoc":"50°"},{"de":"Góc $A = 30^{\\circ}$, $BC = 6$, $R$?","dapAn":"$6$","giaiThich":"Góc $BOC = 60^{\\circ}$, tam giác $OBC$ đều.","dapAnGoc":"6"}]'::jsonb),
  ('VBH-GNT-02', 'Hai hệ quả "vàng": đường kính tạo góc vuông, cùng cung thì bằng nhau.', 'Góc nội tiếp chắn nửa đường tròn bằng $90^{\circ}$. Các góc nội tiếp cùng chắn một cung thì bằng nhau.', '[{"de":"$AB$ là đường kính, góc $CAB = 30^{\\circ}$, góc $CBA$?","giai":"Cách nghĩ sai: không tính được. Cách đúng: góc $ACB = 90^{\\circ}$ nên góc $CBA = 60^{\\circ}$."},{"de":"$ACB = 42^{\\circ}$, $ADB$ cùng chắn cung $AB$.","giai":"$ADB = 42^{\\circ}$."}]'::jsonb, '[{"de":"Góc chắn nửa đường tròn?","dapAn":"$90^{\\circ}$","giaiThich":"Hệ quả.","dapAnGoc":"90°"},{"de":"Hai góc cùng chắn một cung có bằng nhau?","dapAn":"Có","giaiThich":"Hệ quả.","dapAnGoc":"Có"}]'::jsonb),
  ('VBH-NTT-01', '"Ngoại tiếp" là vòng tròn đi qua các đỉnh — nên tâm phải cách đều các đỉnh.', 'Tâm đường tròn ngoại tiếp $=$ giao điểm ba đường trung trực, $OA = OB = OC$. Chỉ cần vẽ hai đường trung trực.', '[{"de":"Tâm ngoại tiếp là trọng tâm?","giai":"Cách nghĩ sai: đúng. Cách đúng: trọng tâm là giao các trung tuyến; tâm ngoại tiếp là giao các trung trực (chỉ trùng nhau ở tam giác đều)."},{"de":"Trạm cách đều ba nhà $A$, $B$, $C$.","giai":"Đặt tại giao các đường trung trực của tam giác $ABC$."}]'::jsonb, '[{"de":"Tam giác tù, tâm ngoại tiếp ở đâu?","dapAn":"Ngoài tam giác","giaiThich":"Tính chất.","dapAnGoc":"Ngoài tam giác"},{"de":"$OA = OB = OC = 5$, $R$?","dapAn":"$5$","giaiThich":"Định nghĩa.","dapAnGoc":"5"}]'::jsonb),
  ('VBH-NTT-02', 'Hai tam giác đặc biệt có bán kính tính nhanh: tam giác vuông và tam giác đều.', 'Tam giác vuông: $R =$ cạnh huyền : $2$. Tam giác đều cạnh $a$: đường cao $h = a\sqrt{3}/2$, $R = 2$h$/3 = a\sqrt{3}/3$, $r = \dfrac{h}{3} = a\sqrt{3}/6$.', '[{"de":"Tam giác đều cạnh $6$, tìm $R$.","giai":"Cách nghĩ sai: $R = 3\\sqrt{3}$ (đường cao). Cách đúng: $h = 3\\sqrt{3}$, $R = 2$h$/3 = 2\\sqrt{3}$."},{"de":"Tam giác vuông $6$, $8$, $10$, tìm $R$.","giai":"$R = 10 : 2 = 5$."}]'::jsonb, '[{"de":"Tam giác đều cạnh $6$, $r$?","dapAn":"$\\sqrt{3}$","giaiThich":"$\\dfrac{h}{3}$.","dapAnGoc":"√3"},{"de":"Tam giác đều nội tiếp đường tròn $R = 4$, cạnh?","dapAn":"$4\\sqrt{3}$","giaiThich":"$a = R\\sqrt{3}$.","dapAnGoc":"4√3"}]'::jsonb),
  ('VBH-NTT-03', '"Nội tiếp" là vòng tròn nằm trong, chạm ba cạnh — nên tâm phải cách đều ba cạnh.', 'Tâm đường tròn nội tiếp $=$ giao điểm ba đường phân giác trong, cách đều ba cạnh, luôn ở trong tam giác.', '[{"de":"Vòi phun cách đều ba bờ rào đặt ở đâu?","giai":"Cách nghĩ sai: giao các trung trực. Cách đúng: \"cách đều ba cạnh\" là giao các đường phân giác."},{"de":"Tam giác vuông $6$, $8$, $10$, tìm $r$.","giai":"$r = (6 + 8 - 10)/2 = 2$."}]'::jsonb, '[{"de":"Tâm nội tiếp là giao đường gì?","dapAn":"Phân giác","giaiThich":"Tính chất.","dapAnGoc":"Phân giác"},{"de":"Tâm nội tiếp có thể nằm ngoài tam giác?","dapAn":"Không","giaiThich":"Luôn ở trong.","dapAnGoc":"Không"}]'::jsonb),
  ('VBH-TGNT-01', 'Tứ giác nội tiếp có "luật cân bằng": hai góc đối cộng lại đúng $180^{\circ}$.', '$ABCD$ nội tiếp $\Leftrightarrow$ góc $A +$ góc $C = 180^{\circ}$ (hoặc góc $B +$ góc $D = 180^{\circ}$). Hai đỉnh cùng nhìn một đoạn dưới góc vuông thì cùng nằm trên đường tròn đường kính đó.', '[{"de":"Góc $A = 70^{\\circ}$, góc $C$?","giai":"Cách nghĩ sai: $70^{\\circ}$. Cách đúng: $180^{\\circ} - 70^{\\circ} = 110^{\\circ}$."},{"de":"$BE$, $CF$ là đường cao của tam giác $ABC$.","giai":"Góc $BEC =$ góc $BFC = 90^{\\circ}$ cùng nhìn $BC$ nên $B$, $C$, $E$, $F$ cùng thuộc đường tròn đường kính $BC$."}]'::jsonb, '[{"de":"Góc $B = 95^{\\circ}$, góc $D$?","dapAn":"$85^{\\circ}$","giaiThich":"$180^{\\circ} - 95^{\\circ}$.","dapAnGoc":"85°"},{"de":"Góc $A = 2$ góc $C$, góc $A$?","dapAn":"$120^{\\circ}$","giaiThich":"$A + C = 180^{\\circ}$.","dapAnGoc":"120°"}]'::jsonb),
  ('VBH-TGNT-02', 'Hình chữ nhật, hình vuông luôn "vừa khít" trong một đường tròn có đường kính là đường chéo.', 'Tâm $=$ giao điểm hai đường chéo; $R =$ đường chéo : $2$. Hình vuông cạnh $a$: $R = a\sqrt{2}/2$, ngược lại $a = R\sqrt{2}$. Hình thoi, hình bình hành (không phải chữ nhật) không nội tiếp được.', '[{"de":"Hình vuông cạnh $4$, $R$?","giai":"Cách nghĩ sai: $R = 4$. Cách đúng: đường chéo $4\\sqrt{2}$, $R = 2\\sqrt{2}$."},{"de":"Hình thoi góc $60^{\\circ}$ có nội tiếp được?","giai":"Không: hai góc đối $60^{\\circ} + 60^{\\circ} \\ne 180^{\\circ}$."}]'::jsonb, '[{"de":"Chữ nhật $6 \\times 8$, $R$?","dapAn":"$5$","giaiThich":"Chéo $10$.","dapAnGoc":"5"},{"de":"Hình vuông nội tiếp $R = 5$, diện tích?","dapAn":"$50$","giaiThich":"Cạnh $5\\sqrt{2}$.","dapAnGoc":"50"}]'::jsonb),
  ('VBH-DGD-01', 'Đa giác đều cần "hai chữ đều": đều cạnh và đều góc.', 'Đa giác đều là đa giác lồi có mọi cạnh bằng nhau và mọi góc bằng nhau. Thiếu một điều kiện là không phải.', '[{"de":"Hình thoi có là đa giác đều?","giai":"Cách nghĩ sai: có vì $4$ cạnh bằng nhau. Cách đúng: các góc không bằng nhau (trừ hình vuông) nên không phải."},{"de":"Số đường chéo lục giác lồi?","giai":"$6 \\cdot 3 : 2 = 9$."}]'::jsonb, '[{"de":"Hình vuông có là đa giác đều?","dapAn":"Có","giaiThich":"Đủ hai điều kiện.","dapAnGoc":"Có"},{"de":"Hình chữ nhật $2 \\times 3$?","dapAn":"Không","giaiThich":"Cạnh khác nhau.","dapAnGoc":"Không"}]'::jsonb),
  ('VBH-DGD-02', 'Một công thức cho tổng, chia $n$ cho từng góc.', 'Tổng góc trong $= (n - 2)\cdot 180^{\circ}$. Đa giác đều: mỗi góc $= (n - 2)\cdot 180^{\circ}/n$; mỗi góc ngoài $= 360^{\circ}/n$.', '[{"de":"Mỗi góc lục giác đều?","giai":"Cách nghĩ sai: $720^{\\circ}$ (là tổng). Cách đúng: $720^{\\circ} : 6 = 120^{\\circ}$."},{"de":"Góc trong $150^{\\circ}$, mấy cạnh?","giai":"Góc ngoài $30^{\\circ}$, $n = 360 : 30 = 12$."}]'::jsonb, '[{"de":"Mỗi góc ngũ giác đều?","dapAn":"$108^{\\circ}$","giaiThich":"$540^{\\circ} : 5$.","dapAnGoc":"108°"},{"de":"Tổng góc trong $1 080^{\\circ}$, $n$?","dapAn":"$8$","giaiThich":"$(n - 2)\\cdot 180 = 1 080$.","dapAnGoc":"8"}]'::jsonb),
  ('VBH-PQ-01', 'Quay là "xoay quanh một chốt": khoảng cách tới chốt giữ nguyên, chỉ góc thay đổi.', 'Phép quay tâm $O$ góc $\alpha$: $OA'' = OA$, góc $AOA'' = \alpha$, theo chiều đã cho (ngược chiều kim đồng hồ là chiều dương). Tâm $O$ không đổi.', '[{"de":"Quay $A(2; 0)$ quanh $O$ góc $90^{\\circ}$ ngược chiều kim đồng hồ.","giai":"Cách nghĩ sai: $(0; -2)$. Cách đúng: ngược chiều kim đồng hồ đi lên: $(0; 2)$."},{"de":"Kim phút $15$ phút quay bao nhiêu?","giai":"$15 \\cdot 6^{\\circ} = 90^{\\circ}$."}]'::jsonb, '[{"de":"Quay $180^{\\circ}$ quanh $O$, $O$ là gì của $AA''$?","dapAn":"Trung điểm","giaiThich":"$OA = OA''$, thẳng hàng.","dapAnGoc":"Trung điểm"},{"de":"$2{,}5$ vòng bằng?","dapAn":"$900^{\\circ}$","giaiThich":"$2{,}5 \\cdot 360^{\\circ}$.","dapAnGoc":"900°"}]'::jsonb),
  ('VBH-PQ-02', 'Đa giác đều $n$ cạnh "trùng lại chính nó" sau mỗi lần quay $360^{\circ}/n$.', 'Phép quay tâm $O$ giữ nguyên đa giác đều $n$ cạnh: góc $k\cdot 360^{\circ}/n$ ($k = 1$…$n$). Đây là góc ở tâm, không phải góc trong.', '[{"de":"Ngũ giác đều: phép quay $108^{\\circ}$ có giữ nguyên?","giai":"Cách nghĩ sai: có ($108^{\\circ}$ là góc trong). Cách đúng: góc quay phải là bội của $360^{\\circ}/5 = 72^{\\circ}$."},{"de":"Lục giác đều, quay $60^{\\circ}$.","giai":"Mỗi đỉnh chuyển sang đỉnh kế tiếp."}]'::jsonb, '[{"de":"Bát giác đều, góc nhỏ nhất?","dapAn":"$45^{\\circ}$","giaiThich":"$360 : 8$.","dapAnGoc":"45°"},{"de":"Hình vuông có mấy phép quay $(0^{\\circ} < \\alpha \\le 360^{\\circ})$?","dapAn":"$4$","giaiThich":"$90^{\\circ}$, $180^{\\circ}$, $270^{\\circ}$, $360^{\\circ}$.","dapAnGoc":"4"}]'::jsonb)
on conflict (content_id) do update set dan = excluded.dan, quy_tac = excluded.quy_tac,
  vi_du = excluded.vi_du, tu_lam = excluded.tu_lam, updated_at = now();

