  ('VBH-TRU-01', 'C10-B31-M1', 'micro-lesson', 1, 'Vi bài học: Bán kính = đường kính : 2; cạnh quay quanh là chiều cao', 300, null, null),
  ('VBH-TRU-02', 'C10-B31-M2', 'micro-lesson', 1, 'Vi bài học: Sxq = 2πrh; Stp = 2πrh + 2πr²; V = πr²h', 300, null, null),
  ('VBH-NON-01', 'C10-B31-M3', 'micro-lesson', 1, 'Vi bài học: l² = h² + r²; Sxq dùng l, V dùng h', 300, null, null),
  ('VBH-NON-02', 'C10-B31-M4', 'micro-lesson', 1, 'Vi bài học: Sxq = πrl; V = (1/3)πr²h', 300, null, null),
  ('VBH-CAU-01', 'C10-B32-M1', 'micro-lesson', 1, 'Vi bài học: R = đường kính : 2; cắt qua tâm được hình tròn lớn', 300, null, null),
  ('VBH-CAU-02', 'C10-B32-M2', 'micro-lesson', 1, 'Vi bài học: S = 4πR²; V = (4/3)πR³', 300, null, null)
-- Link video: chỉ điền khi ô còn trống — link giáo viên đã tự gắn ở /gv/noi-dung được giữ nguyên.
on conflict (content_id) do update set title = excluded.title, ku_id = excluded.ku_id,
  duration_sec = case when contents.url is null or contents.url = '' then excluded.duration_sec else contents.duration_sec end,
  nguon = case when contents.url is null or contents.url = '' then excluded.nguon else contents.nguon end,
  url = case when contents.url is null or contents.url = '' then excluded.url else contents.url end;

insert into error_dictionary (error_code, ku_id, misconception, remediation_id) values
  ('E-TRU-01', 'C10-B31-M1', 'Dùng đường kính thay bán kính, hoặc nhầm cạnh làm trục quay với cạnh tạo nên bán kính đáy. Ví dụ: Quay hình chữ nhật 3 × 5 quanh cạnh 3 được hình trụ bán kính 3', 'VBH-TRU-01'),
  ('E-TRU-02', 'C10-B31-M2', 'Nhầm Sxq với thể tích, quên thừa số 2, quên hai đáy khi tính diện tích toàn phần. Ví dụ: r = 3, h = 5: Sxq = πrh = 15π', 'VBH-TRU-02'),
  ('E-NON-01', 'C10-B31-M3', 'Dùng chiều cao thay đường sinh khi tính diện tích xung quanh (hoặc ngược lại khi tính thể tích), tính sai l từ h và r. Ví dụ: h = 4, r = 3: l = 7', 'VBH-NON-01'),
  ('E-NON-02', 'C10-B31-M4', 'Quên thừa số 1/3 trong thể tích hình nón, hoặc dùng 2πrl như hình trụ. Ví dụ: r = 3, h = 4: V = 36π', 'VBH-NON-02'),
  ('E-CAU-01', 'C10-B32-M1', 'Nhầm mặt cầu với hình cầu, dùng đường kính thay bán kính, tính sai bán kính mặt cắt. Ví dụ: Bóng đường kính 20 cm: S = 4π·20²', 'VBH-CAU-01'),
  ('E-CAU-02', 'C10-B32-M2', 'Tính diện tích mặt cầu bằng πR², thể tích bằng 4πR² hoặc πR³ (thiếu 4/3). Ví dụ: R = 6: V = 4π·6² = 144π (đúng phải là 288π)', 'VBH-CAU-02')
on conflict (error_code) do update set ku_id = excluded.ku_id, misconception = excluded.misconception,
  remediation_id = excluded.remediation_id;

